INSERT INTO `courses` (`id`,`category_id`,`code`,`slug`,`title`,`subtitle`,`summary`,`description`,`objectives`,`skills`,`prerequisites`,`level`,`duration_hours`,`is_featured`,`status`,`sort_order`) VALUES
(1,1,'AFS-A101','fondements-du-renseignement','Fondements du renseignement','Cycle, histoire et méthodes d''analyse : le socle commun de tous les métiers de l''intelligence.','Comprendre ce qu''est le renseignement, d''où il vient, comment il se produit et comment l''information brute devient un produit d''aide à la décision fiable, sourcé et éthique.','<p>Cette formation pose les bases indispensables à tout parcours AFRICA''SPY. Elle distingue <strong>l''information</strong> (donnée brute), <strong>le renseignement</strong> (information évaluée, recoupée et mise en perspective pour un décideur) et <strong>la connaissance</strong> (savoir durable accumulé par une organisation).</p><p>Vous étudierez le cycle du renseignement, les grandes étapes de l''histoire des services — en accordant une place réelle aux expériences africaines —, la typologie des disciplines de collecte et les méthodes structurées d''analyse qui permettent de lutter contre les biais cognitifs.</p><p>Tout au long du parcours, le cadre légal et éthique est traité comme une compétence professionnelle à part entière, et non comme une contrainte annexe.</p>','Définir le renseignement et le distinguer de l''information et de la connaissance\nDécrire chaque phase du cycle du renseignement et ses points de défaillance\nSituer les grandes évolutions historiques des services, dont les trajectoires africaines\nIdentifier les principales disciplines de collecte et leurs limites\nAppliquer deux méthodes d''analyse structurée à un problème simple','Formuler un besoin en renseignement précis\nÉvaluer une information selon sa source et sa crédibilité\nRédiger une synthèse analytique courte et sourcée\nReconnaître les biais cognitifs courants\nRaisonner en hypothèses concurrentes','Aucun prérequis technique\nBonne maîtrise du français écrit\nCuriosité pour l''actualité internationale et africaine','fondamental',14,1,'published',1),
(2,1,'AFS-A201','disciplines-de-collecte','Disciplines de collecte : HUMINT, OSINT, SIGINT, GEOINT','Fonctionnement, apports et cadre juridique des grandes familles de sources.','Une immersion méthodique dans les quatre grandes disciplines de collecte, avec leurs usages légitimes, leurs limites et les garde-fous légaux qui les encadrent.','<p>Après les fondements, cette formation approfondit les quatre disciplines de collecte les plus structurantes. L''objectif n''est pas de former des opérateurs techniques mais des <strong>professionnels capables de comprendre, commander et exploiter</strong> ces sources de manière éclairée.</p><p>Chaque chapitre précise ce qu''un acteur privé ou un chercheur peut faire légalement, et ce qui relève exclusivement des autorités publiques habilitées par la loi.</p>','Expliquer le fonctionnement et l''apport de chaque discipline\nDistinguer les activités ouvertes à tous de celles réservées aux autorités habilitées\nMener une recherche OSINT méthodique et documentée\nLire et interpréter une image satellitaire simple\nCroiser plusieurs disciplines dans un produit unique','Planifier une recherche en sources ouvertes\nDocumenter la traçabilité de ses sources\nInterpréter des indices géospatiaux\nIdentifier les contraintes légales d''une collecte\nArticuler plusieurs disciplines','Avoir suivi « Fondements du renseignement » ou disposer de connaissances équivalentes\nAisance avec les outils numériques courants','intermediaire',18,0,'published',2),
(3,2,'AFS-B101','renseignement-humain-principes-ethique','Renseignement humain : principes et éthique','Entretien, observation et évaluation des sources, dans un cadre légal et respectueux des personnes.','Maîtriser les principes du renseignement d''origine humaine tels qu''ils peuvent être pratiqués légalement : conduite d''entretiens consentis, observation non intrusive et évaluation rigoureuse de la fiabilité des sources.','<p>Le renseignement humain fascine autant qu''il inquiète. Cette formation le ramène à ce qu''il est dans la pratique professionnelle légitime : <strong>l''art de recueillir, auprès de personnes consentantes, des informations fiables et utiles</strong>, puis de les évaluer avec méthode.</p><p>Les compétences enseignées sont directement transposables à l''analyse de risques, à l''enquête interne, au journalisme, à la recherche de terrain et à la diplomatie.</p>','Expliquer les principes fondamentaux du renseignement humain\nIdentifier les limites légales et déontologiques de la collecte\nPréparer et conduire un entretien d''information consenti\nPratiquer une observation non intrusive d''un environnement public\nÉvaluer une source et une information selon une grille standard','Préparer un guide d''entretien\nPratiquer l''écoute active et le questionnement ouvert\nNoter et restituer fidèlement des propos\nCoter une source (fiabilité / crédibilité)\nIdentifier les signaux de manipulation','Fondements du renseignement recommandés\nQualités relationnelles et sens de l''écoute','intermediaire',16,1,'published',3),
(4,2,'AFS-B201','protection-des-sources-et-redaction','Protection des sources, analyse comportementale et rédaction','Protéger ceux qui parlent, interpréter avec prudence, écrire pour décider.','Trois compétences qui distinguent le professionnel : garantir la confidentialité de ses sources, faire un usage scientifiquement honnête de l''analyse comportementale et rédiger des rapports clairs, sourcés et actionnables.','<p>Cette formation avancée complète le parcours HUMINT. Elle aborde la <strong>protection des sources</strong> comme une obligation morale et juridique, déconstruit les mythes de la « détection du mensonge » à la lumière de la recherche scientifique, et entraîne à la rédaction de produits de renseignement de qualité professionnelle.</p>','Mettre en place des mesures de protection et de confidentialité des sources\nDistinguer les apports réels et les limites scientifiques de l''analyse comportementale\nRédiger un rapport de renseignement structuré, sourcé et nuancé\nAdapter un produit écrit à son destinataire','Pseudonymiser et cloisonner des informations sensibles\nÉviter les conclusions abusives fondées sur le non-verbal\nAppliquer la structure BLUF (conclusion d''abord)\nUtiliser un vocabulaire de probabilité normalisé','Renseignement humain : principes et éthique (recommandé)\nTrès bonne expression écrite','avance',14,0,'published',4),
(5,3,'AFS-C101','contre-espionnage-menaces-protection','Contre-espionnage : menaces et protection de l''information','Identifier les menaces d''ingérence et protéger ce qui compte vraiment.','Comprendre les logiques d''ingérence et d''espionnage visant les organisations africaines, détecter les menaces internes et l''ingénierie sociale, et mettre en place une protection proportionnée des informations sensibles.','<p>Le contre-espionnage n''est pas l''apanage des États. Entreprises, administrations, universités, ONG et startups africaines détiennent des informations convoitées : appels d''offres, données clients, savoir-faire, positions de négociation, résultats de recherche.</p><p>Cette formation adopte une approche <strong>strictement défensive</strong> : comprendre les modes opératoires pour mieux s''en protéger, sans jamais basculer dans la surveillance abusive des personnels.</p>','Définir le contre-espionnage et ses finalités défensives\nIdentifier les principaux vecteurs d''ingérence visant les organisations\nComprendre la menace interne sans stigmatiser les personnels\nClassifier et protéger les informations sensibles\nReconnaître et contrer les tentatives d''ingénierie sociale','Cartographier les actifs informationnels sensibles\nMettre en place une politique de classification simple\nSensibiliser des équipes aux manipulations\nRédiger une procédure de signalement','Fondements du renseignement recommandés\nExpérience professionnelle en organisation appréciée','intermediaire',16,1,'published',5),
(6,3,'AFS-C201','securite-organisationnelle-contre-mesures','Sécurité organisationnelle et contre-mesures défensives','Sécurité du personnel, analyse des menaces et exercices de simulation.','Construire une posture de sécurité organisationnelle complète : protection des personnes, analyse structurée des menaces, contre-mesures défensives et entraînement par la simulation.','<p>Ce second volet du module C s''adresse aux responsables sécurité, risk managers et cadres dirigeants. Il relie les dimensions humaine, physique, numérique et organisationnelle de la sécurité dans une démarche cohérente fondée sur l''analyse de risques.</p>','Organiser la sécurité des personnels, y compris en déplacement\nConduire une analyse de menaces structurée\nSélectionner des contre-mesures proportionnées\nConcevoir et animer un exercice de simulation de crise','Réaliser une matrice de risques\nRédiger un plan de sécurité des déplacements\nPrioriser des contre-mesures selon leur coût et leur efficacité\nAnimer un exercice sur table','Contre-espionnage : menaces et protection de l''information\nResponsabilités managériales ou en sécurité appréciées','avance',18,0,'published',6),
(7,4,'AFS-D101','renseignement-numerique-osint-avance','Renseignement numérique et OSINT avancé','Cyberespionnage, empreintes numériques et investigation sur métadonnées.','Comprendre les mécanismes du cyberespionnage, conduire des recherches OSINT avancées, analyser des empreintes numériques et exploiter les métadonnées — exclusivement sur données synthétiques et dans des scénarios autorisés.','<p>Le numérique est devenu le principal terrain de collecte et d''affrontement informationnel. Cette formation donne aux analystes la culture technique nécessaire pour <strong>comprendre les menaces</strong> et <strong>mener des investigations ouvertes rigoureuses</strong>.</p><p><strong>Cadre pédagogique :</strong> tous les exercices utilisent des environnements isolés, des jeux de données synthétiques fournis par l''Académie et des scénarios fictifs. Aucune technique d''intrusion n''est enseignée.</p>','Expliquer les modes opératoires du cyberespionnage\nConduire une recherche OSINT avancée méthodique et légale\nAnalyser une empreinte numérique organisationnelle\nExtraire et interpréter des métadonnées de fichiers\nDocumenter une investigation de façon reproductible','Utiliser des opérateurs de recherche avancés\nPivoter entre indicateurs (domaine, IP, certificat)\nLire les métadonnées EXIF et documentaires\nRéduire sa propre empreinte numérique','Disciplines de collecte (recommandé)\nBonne pratique de l''informatique (navigateur, fichiers, tableur)','avance',20,1,'published',7),
(8,4,'AFS-D201','cyber-threat-intelligence-defense','Cyber Threat Intelligence et défense des communications','CTI, infrastructures, communications sécurisées et détection.','Produire et exploiter du renseignement sur les menaces cyber (CTI), analyser des infrastructures numériques, sécuriser les communications et détecter les activités suspectes à partir de journaux synthétiques.','<p>La Cyber Threat Intelligence transforme des données techniques en <strong>décisions de défense</strong>. Cette formation fait le lien entre analystes de renseignement et équipes techniques (SOC, CSIRT), en couvrant les niveaux stratégique, opérationnel et tactique de la CTI.</p><p>Les travaux pratiques reposent sur des journaux et indicateurs synthétiques fournis par l''Académie.</p>','Définir la CTI et ses trois niveaux\nUtiliser le modèle en diamant et MITRE ATT&CK\nAnalyser une infrastructure numérique à partir de données publiques\nMettre en place des communications sécurisées\nDétecter des activités suspectes dans des journaux','Structurer un rapport CTI\nQualifier des indicateurs de compromission\nChoisir des outils de communication chiffrée\nLire des journaux d''authentification','Renseignement numérique et OSINT avancé\nNotions de réseaux informatiques (adresse IP, DNS)','avance',20,0,'published',8),
(9,5,'AFS-E101','outils-du-renseignement','Outils du renseignement : usages légitimes','Logiciels d''investigation et équipements professionnels, de la prise en main à l''éthique d''usage.','Découvrir les principaux outils logiciels et matériels de l''analyste — Maltego, SpiderFoot, theHarvester, Shodan, Google Earth, Wireshark, Autopsy, Volatility, Recon-ng et équipements d''observation — avec leurs usages légitimes, leurs limites et leur cadre légal.','<p>Un outil n''est ni bon ni mauvais : c''est l''usage, le mandat et le cadre légal qui le rendent légitime. Cette formation présente les outils de référence de l''investigation numérique et de l''observation professionnelle, <strong>pour des usages défensifs, journalistiques, académiques et d''enquête autorisée</strong>.</p><p>La galerie visuelle de l''Académie (page « Outils ») complète ce cours avec des fiches descriptives détaillées.</p>','Connaître la fonction et l''usage légitime des principaux outils logiciels\nChoisir l''outil adapté à une question d''investigation\nComprendre les principes de l''investigation numérique légale (forensique)\nConnaître les équipements d''observation et de protection documentaire\nAppliquer une grille d''évaluation éthique avant tout usage','Construire un graphe de relations à partir de données publiques\nLire une capture réseau sur son propre réseau\nComprendre une chaîne de traitement forensique\nRédiger une note de cadrage d''usage d''outil','Disciplines de collecte (recommandé)\nAisance informatique','intermediaire',16,1,'published',9),
(10,6,'AFS-F101','intelligence-economique-veille-strategique','Intelligence économique et veille stratégique','Anticiper, protéger et influencer légalement dans l''économie africaine.','Mettre en place un dispositif d''intelligence économique : veille stratégique, protection des intérêts économiques et production de notes stratégiques à destination des décideurs.','<p>Avec la Zone de libre-échange continentale africaine (ZLECAf), l''essor des entreprises africaines et la compétition mondiale pour les ressources, l''intelligence économique devient un levier de souveraineté. Cette formation en présente les trois piliers : <strong>veille</strong>, <strong>protection</strong> et <strong>influence légitime</strong>.</p>','Définir l''intelligence économique et ses trois piliers\nConcevoir un dispositif de veille stratégique\nIdentifier et protéger les intérêts économiques d''une organisation\nRédiger une note stratégique claire et argumentée','Définir des axes de veille\nSélectionner et qualifier des sources\nProduire un bulletin de veille\nStructurer une note stratégique','Aucun prérequis\nIntérêt pour l''économie et les entreprises','fondamental',14,1,'published',10),
(11,6,'AFS-F201','geopolitique-africaine-risques-pays','Géopolitique africaine, conflits et risques pays','Lire les dynamiques du continent pour anticiper les risques.','Analyser les grandes dynamiques géopolitiques africaines, comprendre les conflits et évaluer méthodiquement le risque pays pour éclairer les décisions d''investissement, de coopération ou d''implantation.','<p>L''Afrique n''est pas un bloc : 54 États, des communautés économiques régionales, des espaces transfrontaliers et des dynamiques très contrastées. Cette formation donne des grilles de lecture rigoureuses et nuancées, loin des clichés, pour analyser les situations et évaluer les risques.</p>','Identifier les grandes dynamiques géopolitiques du continent\nAnalyser un conflit selon une grille structurée\nConduire une analyse de risque pays complète\nÉviter les biais et stéréotypes dans l''analyse','Utiliser une grille d''analyse de conflit\nConstruire une matrice de risque pays\nIdentifier les sources régionales fiables\nFormuler des scénarios prospectifs','Intelligence économique et veille stratégique (recommandé)\nCulture générale en histoire et relations internationales','avance',16,0,'published',11);
INSERT INTO `chapters` (`id`,`course_id`,`title`,`summary`,`sort_order`) VALUES
(1,1,'Introduction au renseignement','Définitions, finalités et cycle du renseignement.',1),
(2,1,'Histoire des services de renseignement','Des messagers royaux aux agences contemporaines, avec un regard africain.',2),
(3,1,'Les différentes disciplines du renseignement','Panorama des « INT » et complémentarité des sources.',3),
(4,1,'Analyse et exploitation de l''information','Évaluer, recouper, raisonner en hypothèses, exprimer l''incertitude.',4),
(5,1,'Atelier pratique','Exercice guidé et étude de cas de synthèse.',5),
(6,2,'Renseignement humain : HUMINT','Ce que les personnes peuvent apporter, et à quelles conditions.',1),
(7,2,'Renseignement de sources ouvertes : OSINT','Méthode, traçabilité et légalité de la recherche ouverte.',2),
(8,2,'Renseignement d''origine électromagnétique : SIGINT','Comprendre une discipline réservée aux États, et ses garde-fous.',3),
(9,2,'Renseignement géospatial : GEOINT','Lire le territoire à partir d''images et de données géographiques.',4),
(10,2,'Atelier pratique','Exercice de recherche ouverte et étude de cas multi-sources.',5),
(11,3,'Principes fondamentaux du renseignement humain','Relation, besoin, confiance et responsabilité.',1),
(12,3,'Collecte éthique et légale d''informations','Le droit applicable et les lignes rouges.',2),
(13,3,'Techniques d''entretien et d''observation non intrusive','Conduire un entretien d''information et observer un espace public.',3),
(14,3,'Évaluation de la fiabilité des sources','La cotation à deux dimensions et la détection des manipulations.',4),
(15,3,'Atelier pratique','Simulation d''entretien et étude de cas sur la cotation.',5),
