INSERT INTO `lessons` (`id`,`chapter_id`,`title`,`type`,`content`,`video_url`,`media_id`,`duration_minutes`,`is_downloadable`,`sort_order`) VALUES
(1,1,'Briefing vidéo : le métier d''analyste','video','<p>Ce briefing visuel présente en quelques minutes les notions clés de la formation : la différence entre information et renseignement, le cycle de production et les exigences éthiques du métier. Il ne comporte pas de narration : prenez le temps de lire chaque écran.</p>',NULL,1,4,1,1),
(2,1,'Qu''est-ce que le renseignement ?','text','<p>Le renseignement est <strong>une information élaborée pour éclairer une décision</strong>. Il se définit moins par la nature de ses sources que par sa finalité : réduire l''incertitude d''un décideur — chef d''État, dirigeant d''entreprise, responsable de la sécurité d''une organisation — face à une situation qui le concerne.</p>\n<h3>Trois niveaux à ne pas confondre</h3>\n<table><thead><tr><th>Niveau</th><th>Définition</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Donnée / information</td><td>Fait brut, non évalué</td><td>« Un convoi de camions a été vu près de la frontière. »</td></tr>\n<tr><td>Renseignement</td><td>Information évaluée, recoupée, interprétée pour un besoin précis</td><td>« Le convoi correspond probablement à une rotation logistique saisonnière ; aucun indice de menace (confiance modérée). »</td></tr>\n<tr><td>Connaissance</td><td>Savoir accumulé et structuré dans la durée</td><td>Base documentaire sur les flux commerciaux transfrontaliers de la région.</td></tr>\n</tbody></table>\n<h3>Les trois niveaux de décision</h3>\n<ul>\n<li><strong>Stratégique</strong> : grandes orientations, horizon de plusieurs années (stabilité régionale, dépendances économiques).</li>\n<li><strong>Opérationnel</strong> : conduite d''un ensemble d''actions sur une zone ou un secteur.</li>\n<li><strong>Tactique</strong> : décision immédiate, sur le terrain ou en situation de crise.</li>\n</ul>\n<h3>Le cycle du renseignement</h3>\n<p>La production suit un cycle classique en cinq phases, qui structure tout le reste du parcours :</p>\n<ol>\n<li><strong>Orientation</strong> : le décideur exprime un besoin ; l''analyste le traduit en questions précises (<em>besoins en renseignement</em>).</li>\n<li><strong>Collecte</strong> : recherche d''informations par des moyens légaux et adaptés.</li>\n<li><strong>Exploitation</strong> : tri, traduction, mise en forme, évaluation des sources.</li>\n<li><strong>Analyse</strong> : interprétation, recoupement, formulation de jugements avec un niveau de confiance.</li>\n<li><strong>Diffusion</strong> : livraison d''un produit clair au bon destinataire, au bon moment, puis retour d''expérience.</li>\n</ol>\n<div class="callout"><strong>À retenir.</strong> Un renseignement exact mais livré trop tard ou au mauvais destinataire n''a aucune valeur. La pertinence et le délai font partie de la qualité.</div>\n<h3>Ce que le renseignement n''est pas</h3>\n<p>Le renseignement n''est ni de la surveillance indiscriminée, ni de la propagande, ni une activité au-dessus des lois. Dans un État de droit, il s''exerce dans un cadre légal, sous contrôle, avec des finalités définies. C''est ce cadre qui garantit sa légitimité et, à terme, son efficacité.</p>',NULL,NULL,20,1,2),
(3,2,'Grandes étapes historiques','text','<p>L''histoire du renseignement est aussi ancienne que celle du pouvoir politique. Elle éclaire les pratiques actuelles et rappelle que les dérives passées ont conduit à l''instauration de contrôles démocratiques.</p>\n<h3>Antiquité et royaumes africains</h3>\n<p>Les traités militaires anciens, dont <em>L''Art de la guerre</em> attribué à Sun Tzu, consacrent déjà un chapitre à l''emploi des informateurs. En Afrique, les grands ensembles politiques — empires du Ghana, du Mali et Songhaï, royaume du Dahomey, empire éthiopien, royaumes swahilis — s''appuyaient sur des réseaux de messagers, de commerçants caravaniers et de conseillers chargés de rapporter la situation des provinces et des voisins. Les routes transsahariennes étaient autant des voies d''échange que des canaux d''information.</p>\n<h3>L''âge des cabinets et des chiffres</h3>\n<p>Du XVI<sup>e</sup> au XIX<sup>e</sup> siècle, les monarchies européennes structurent des « cabinets noirs » chargés d''ouvrir le courrier diplomatique et de déchiffrer les messages. La cryptologie devient une discipline à part entière. La période coloniale voit ensuite les administrations imposer en Afrique des services de police politique tournés vers le contrôle des populations — un héritage que les États indépendants ont dû réformer.</p>\n<h3>Le XX<sup>e</sup> siècle : institutionnalisation</h3>\n<ul>\n<li><strong>Les deux guerres mondiales</strong> industrialisent la collecte (écoutes radio, reconnaissance aérienne) et le décryptement.</li>\n<li><strong>La guerre froide</strong> crée de grandes agences permanentes et fait de l''Afrique un terrain de rivalités extérieures.</li>\n<li><strong>Les indépendances</strong> conduisent les États africains à bâtir leurs propres services, souvent dans l''urgence et parfois au service exclusif du pouvoir en place.</li>\n</ul>\n<h3>Depuis les années 1990 : contrôle et coopération</h3>\n<p>La fin de la guerre froide, puis la montée du terrorisme transnational, de la criminalité organisée et des menaces numériques, ont transformé les priorités. Deux tendances marquent la période : l''encadrement législatif des services (lois, commissions de contrôle, juges) et le développement de coopérations régionales, notamment sous l''égide de l''Union africaine et des communautés économiques régionales.</p>\n<blockquote>Leçon de l''histoire : les services les plus efficaces dans la durée sont ceux qui bénéficient de la confiance des citoyens, donc ceux qui respectent la loi.</blockquote>',NULL,NULL,25,1,1),
(4,3,'Panorama des disciplines de collecte','text','<p>Les professionnels classent les sources par grandes familles, désignées par des acronymes anglais. Chacune a ses forces, ses faiblesses et son cadre juridique propre.</p>\n<table><thead><tr><th>Discipline</th><th>Source</th><th>Atout</th><th>Limite</th></tr></thead><tbody>\n<tr><td><strong>HUMINT</strong></td><td>Personnes</td><td>Intentions, contexte, nuances</td><td>Fiabilité variable, risques humains</td></tr>\n<tr><td><strong>OSINT</strong></td><td>Sources ouvertes et publiques</td><td>Volume, coût, légalité d''accès</td><td>Bruit, désinformation</td></tr>\n<tr><td><strong>SIGINT</strong></td><td>Signaux électromagnétiques</td><td>Couverture, rapidité</td><td>Strictement réservé aux autorités habilitées par la loi</td></tr>\n<tr><td><strong>GEOINT</strong></td><td>Imagerie et données géospatiales</td><td>Vision objective du terrain</td><td>Ne révèle pas les intentions</td></tr>\n<tr><td><strong>FININT</strong></td><td>Flux financiers</td><td>Traçabilité des réseaux</td><td>Accès encadré (cellules de renseignement financier)</td></tr>\n<tr><td><strong>TECHINT</strong></td><td>Matériels et technologies</td><td>Connaissance des capacités</td><td>Expertise rare</td></tr>\n</tbody></table>\n<h3>La fusion des sources (all-source)</h3>\n<p>Aucune discipline ne suffit seule. L''analyste « toutes sources » croise des éléments hétérogènes : une image satellite montre un chantier, un article de presse locale évoque un projet d''infrastructure, un registre public identifie l''entreprise adjudicataire. C''est la convergence d''indices indépendants qui fonde un jugement solide.</p>\n<div class="note"><strong>Principe d''indépendance.</strong> Deux articles qui reprennent la même dépêche ne constituent pas deux sources : ils n''en font qu''une. Remonter à l''origine de l''information est un réflexe fondamental.</div>',NULL,NULL,20,1,1),
(5,4,'Méthodes d''analyse structurée','text','<p>L''analyse consiste à transformer un ensemble d''éléments évalués en <strong>jugements</strong> utiles. Le principal ennemi de l''analyste n''est pas le manque d''information mais <strong>les biais cognitifs</strong>.</p>\n<h3>Biais fréquents</h3>\n<ul>\n<li><strong>Biais de confirmation</strong> : retenir ce qui confirme l''idée initiale.</li>\n<li><strong>Ancrage</strong> : rester prisonnier de la première estimation.</li>\n<li><strong>Effet miroir</strong> : supposer que l''autre raisonne comme nous.</li>\n<li><strong>Pensée de groupe</strong> : consensus artificiel au sein d''une équipe.</li>\n</ul>\n<h3>L''analyse des hypothèses concurrentes (ACH)</h3>\n<p>Méthode formalisée par Richards J. Heuer : on liste <em>toutes</em> les hypothèses plausibles, puis on évalue chaque indice au regard de chacune. On cherche moins les indices qui confirment que ceux qui <strong>infirment</strong>. L''hypothèse retenue est celle qui subit le moins d''incohérences.</p>\n<table><thead><tr><th>Indice</th><th>H1 : exercice logistique</th><th>H2 : préparation d''incident</th><th>H3 : activité commerciale</th></tr></thead><tbody>\n<tr><td>Convoi observé à date habituelle</td><td>Cohérent</td><td>Neutre</td><td>Cohérent</td></tr>\n<tr><td>Aucun discours public hostile</td><td>Cohérent</td><td>Incohérent</td><td>Cohérent</td></tr>\n<tr><td>Marchandises déclarées en douane</td><td>Neutre</td><td>Incohérent</td><td>Cohérent</td></tr>\n</tbody></table>\n<h3>Exprimer l''incertitude</h3>\n<p>Un jugement analytique s''accompagne toujours d''un niveau de confiance et d''un vocabulaire de probabilité stable : <em>presque certain, probable, possible, peu probable</em>. Cette échelle doit être définie à l''avance et partagée avec les lecteurs pour éviter toute ambiguïté.</p>\n<div class="callout"><strong>Bonne pratique :</strong> séparer clairement les <em>faits</em> (ce qui est établi), les <em>jugements</em> (ce que l''on en conclut) et les <em>lacunes</em> (ce que l''on ignore encore).</div>',NULL,NULL,30,1,1),
(6,5,'Fiche de synthèse (PDF)','document','<p>Téléchargez la fiche de synthèse de la formation : définitions, cycle du renseignement, tableau des disciplines, liste des biais et échelle de probabilité. Elle constitue votre aide-mémoire pour l''examen final.</p>',NULL,2,10,1,1),
(7,5,'Exercice : de l''information au renseignement','exercise','<p><strong>Contexte fictif.</strong> Le directeur sécurité d''une entreprise de logistique opérant entre deux pays voisins vous demande si la réouverture annoncée d''un poste frontière présente des risques pour ses convois.</p>\n<h3>Consignes</h3>\n<ol>\n<li>Reformulez la demande en <strong>trois besoins en renseignement</strong> précis et vérifiables.</li>\n<li>Pour chacun, identifiez <strong>deux sources ouvertes légales</strong> que vous consulteriez (journaux officiels, presse régionale, communiqués des douanes, rapports d''organisations régionales…).</li>\n<li>Proposez une <strong>grille d''évaluation</strong> des sources (fiabilité de la source / crédibilité de l''information).</li>\n<li>Rédigez un <strong>jugement analytique de cinq lignes</strong> en séparant faits, jugements et lacunes, avec un niveau de confiance.</li>\n</ol>\n<div class="note"><strong>Corrigé indicatif.</strong> Un bon besoin est daté et mesurable : « Quels sont les horaires et procédures effectifs du poste X depuis sa réouverture ? » plutôt que « Est-ce dangereux ? ». Le jugement doit mentionner explicitement ce qui reste inconnu.</div>',NULL,NULL,40,1,2),
(8,5,'Étude de cas : l''erreur d''analyse','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une cellule d''analyse d''une organisation régionale reçoit, sur trois semaines, une série de signalements de rassemblements dans une ville moyenne. L''analyste principal, convaincu dès le premier jour d''une préparation de troubles, rédige des notes de plus en plus alarmistes. Il s''avère finalement qu''il s''agissait de la préparation d''un festival culturel annuel, annoncée dans la presse locale en langue nationale.</p>\n<h3>Questions d''analyse</h3>\n<ol>\n<li>Quels biais cognitifs identifiez-vous ? À quel moment se sont-ils installés ?</li>\n<li>Quelle source simple aurait permis de lever le doute ? Pourquoi n''a-t-elle pas été consultée ?</li>\n<li>Construisez la matrice ACH qui aurait dû être réalisée dès la première semaine.</li>\n<li>Quelles mesures organisationnelles (relecture contradictoire, « avocat du diable », diversité linguistique de l''équipe) proposeriez-vous ?</li>\n</ol>\n<blockquote>Enseignement : la maîtrise des langues et des contextes locaux est une compétence analytique de premier plan sur le continent africain.</blockquote>',NULL,NULL,35,1,3),
(9,6,'Briefing vidéo : quatre familles de sources','video','<p>Présentation visuelle des quatre disciplines étudiées et de leurs garde-fous juridiques.</p>',NULL,3,4,1,1),
(10,6,'Le renseignement d''origine humaine','text','<p>Le HUMINT regroupe toutes les informations obtenues <strong>auprès de personnes</strong>. Dans sa forme la plus courante et la plus légitime, il ressemble au travail d''un journaliste d''investigation ou d''un chercheur de terrain : entretiens, échanges avec des experts, participation à des conférences, débriefing de voyageurs ou de collaborateurs.</p>\n<h3>Ce qu''apporte le HUMINT</h3>\n<ul><li>Les <strong>intentions</strong> et les motivations, invisibles pour les capteurs techniques ;</li><li>Le <strong>contexte</strong> culturel, linguistique et social ;</li><li>L''accès à des milieux fermés, dans les limites de la loi.</li></ul>\n<h3>Ses fragilités</h3>\n<ul><li>La source peut se tromper, exagérer ou manipuler ;</li><li>Elle peut s''exposer à des risques personnels ;</li><li>La relation peut créer des dépendances ou des conflits d''intérêts.</li></ul>\n<h3>Cadre</h3>\n<p>Le recrutement de sources clandestines relève exclusivement des services de l''État agissant dans un cadre légal. Pour un acteur privé (entreprise, ONG, cabinet de conseil), le HUMINT se limite à des <strong>échanges transparents et consentis</strong> : jamais de corruption, de chantage, de fausse identité ou d''incitation à violer une obligation de confidentialité.</p>\n<div class="warning"><strong>Ligne rouge.</strong> Obtenir d''un salarié des informations couvertes par le secret de son employeur expose à des poursuites (violation du secret des affaires, corruption, complicité). L''éthique est ici aussi une protection juridique.</div>',NULL,NULL,25,1,2),
(11,7,'Méthodologie OSINT','text','<p>L''OSINT exploite les informations <strong>publiquement et légalement accessibles</strong> : presse, publications officielles, registres publics, données ouvertes, travaux académiques, réseaux sociaux publics, imagerie commerciale. On estime souvent qu''une large majorité du renseignement utile à la décision peut être obtenue de cette manière.</p>\n<h3>Une méthode en six temps</h3>\n<ol>\n<li><strong>Cadrer</strong> la question et les limites (ce que l''on ne cherchera pas).</li>\n<li><strong>Planifier</strong> les sources et les mots-clés, y compris dans les langues locales (wolof, haoussa, swahili, amharique, arabe…).</li>\n<li><strong>Collecter</strong> en archivant systématiquement : URL, date, capture, empreinte du fichier.</li>\n<li><strong>Vérifier</strong> : origine, date réelle, géolocalisation, cohérence.</li>\n<li><strong>Analyser</strong> et recouper.</li>\n<li><strong>Restituer</strong> avec les références permettant à un tiers de refaire le chemin.</li>\n</ol>\n<h3>Les limites légales et éthiques</h3>\n<ul>\n<li>« Accessible » ne veut pas dire « librement exploitable » : les lois sur la protection des données personnelles s''appliquent (par exemple la Convention de Malabo de l''Union africaine et les lois nationales).</li>\n<li>Pas de contournement d''authentification, pas de faux profils pour infiltrer des groupes privés, pas de collecte massive de données personnelles sans base légale.</li>\n<li>Principe de <strong>minimisation</strong> : ne collecter que ce qui est nécessaire à la question posée.</li>\n</ul>\n<div class="callout">Un bon livrable OSINT est <strong>reproductible</strong> : un relecteur doit pouvoir retrouver chaque élément grâce aux références et aux captures horodatées.</div>',NULL,NULL,30,1,1),
(12,8,'Le SIGINT : principes et contrôle démocratique','text','<p>Le SIGINT désigne le renseignement issu des <strong>signaux électromagnétiques</strong>. Il se divise traditionnellement en COMINT (communications) et ELINT (signaux électroniques non communicants, comme les radars). Cette formation l''aborde <strong>sous un angle conceptuel, historique et juridique</strong> : l''interception de communications est un acte réservé aux autorités habilitées et strictement encadré par la loi.</p>\n<h3>Pourquoi l''étudier ?</h3>\n<ul><li>Pour comprendre la place de cette discipline dans les politiques de sécurité ;</li><li>Pour mesurer les enjeux de souveraineté numérique et de protection des communications ;</li><li>Pour maîtriser le débat public sur l''équilibre entre sécurité et libertés.</li></ul>\n<h3>Repères historiques</h3>\n<p>Le décryptement des communications a pesé sur l''issue de plusieurs conflits du XX<sup>e</sup> siècle. Les révélations publiques des années 2010 sur la surveillance de masse ont, à l''inverse, montré les risques d''une collecte sans contrôle suffisant et relancé partout la réflexion législative.</p>\n<h3>Les garde-fous d''un État de droit</h3>\n<table><thead><tr><th>Principe</th><th>Traduction concrète</th></tr></thead><tbody>\n<tr><td>Légalité</td><td>Finalités et techniques définies par une loi publique</td></tr>\n<tr><td>Nécessité et proportionnalité</td><td>Mesure ciblée, limitée dans le temps, justifiée par une menace</td></tr>\n<tr><td>Autorisation préalable</td><td>Décision d''une autorité indépendante ou d''un juge</td></tr>\n<tr><td>Contrôle a posteriori</td><td>Commission parlementaire ou administrative indépendante</td></tr>\n<tr><td>Recours</td><td>Possibilité pour un citoyen de saisir une juridiction</td></tr>\n</tbody></table>\n<div class="warning">Toute interception de communications par un particulier ou une entreprise constitue une infraction pénale dans la quasi-totalité des législations. Aucune technique d''interception n''est enseignée à l''Académie.</div>',NULL,NULL,20,1,1),
(13,9,'Imagerie et analyse géospatiale','text','<p>Le GEOINT combine imagerie (satellitaire, aérienne), cartographie et données géoréférencées pour décrire et comprendre une situation sur le terrain. L''essor de l''imagerie commerciale et des programmes ouverts (comme Sentinel du programme européen Copernicus ou Landsat) a démocratisé cette discipline.</p>\n<h3>Notions de base</h3>\n<ul>\n<li><strong>Résolution spatiale</strong> : taille au sol d''un pixel (de 10 m pour Sentinel-2 à moins d''un mètre pour l''imagerie commerciale très haute résolution).</li>\n<li><strong>Résolution temporelle</strong> : fréquence de revisite d''une zone.</li>\n<li><strong>Bandes spectrales</strong> : l''infrarouge permet par exemple d''évaluer l''état de la végétation.</li>\n</ul>\n<h3>Applications légitimes en Afrique</h3>\n<ul><li>Suivi de la déforestation et de l''orpaillage illégal ;</li><li>Évaluation des dégâts après inondations ou sécheresses ;</li><li>Suivi des déplacements de populations à des fins humanitaires ;</li><li>Vérification d''informations diffusées en ligne (géolocalisation d''une vidéo).</li></ul>\n<h3>Méthode de photo-interprétation</h3>\n<p>On observe successivement : la <em>forme</em>, la <em>taille</em>, l''<em>ombre</em> (qui renseigne sur la hauteur et l''heure), la <em>texture</em>, le <em>motif</em> et l''<em>association</em> (ce qui se trouve autour). Comparer deux dates d''une même zone (analyse diachronique) est souvent plus parlant qu''une image isolée.</p>\n<div class="note">Le GEOINT montre <strong>ce qui est</strong>, rarement <strong>pourquoi</strong>. Il doit être croisé avec d''autres sources pour interpréter les intentions.</div>',NULL,NULL,25,1,1),
(14,10,'Fiche de synthèse (PDF)','document','<p>Aide-mémoire des quatre disciplines : définitions, apports, limites et cadre légal.</p>',NULL,4,10,1,1),
(15,10,'Exercice : géolocaliser une image publique','exercise','<p><strong>Objectif.</strong> Apprendre à vérifier la localisation d''une photographie <em>publiée par une institution</em> (communiqué officiel, rapport d''ONG) en n''utilisant que des sources ouvertes, sans jamais chercher à localiser une personne privée.</p>\n<h3>Étapes</h3>\n<ol>\n<li>Relevez les indices visibles : relief, végétation, panneaux, architecture, langue des inscriptions, sens de circulation.</li>\n<li>Formulez une hypothèse de région, puis comparez avec une imagerie satellitaire libre.</li>\n<li>Vérifiez l''heure approximative grâce aux ombres.</li>\n<li>Documentez chaque étape par une capture annotée.</li>\n<li>Concluez avec un niveau de confiance et les éléments manquants.</li>\n</ol>\n<div class="warning">Règle déontologique : l''exercice porte uniquement sur des lieux et non sur des personnes. Ne jamais diffuser l''emplacement d''un domicile privé.</div>',NULL,NULL,45,1,2),
(16,10,'Étude de cas : vérifier une vidéo virale','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une vidéo présentée comme montrant des affrontements récents dans une capitale régionale circule massivement. Plusieurs médias s''apprêtent à la reprendre.</p>\n<h3>Démarche attendue</h3>\n<ol>\n<li><strong>Recherche d''antériorité</strong> par recherche inversée d''images clés : la vidéo a-t-elle déjà circulé ?</li>\n<li><strong>Géolocalisation</strong> via les bâtiments visibles et l''imagerie libre.</li>\n<li><strong>Chronolocalisation</strong> : météo, ombres, événements datés visibles.</li>\n<li><strong>Croisement</strong> avec la presse locale et les communiqués officiels.</li>\n</ol>\n<p><strong>Dénouement :</strong> la vidéo datait de six ans et avait été tournée dans un autre pays. Discutez l''impact qu''aurait eu sa diffusion et le rôle d''un analyste dans la lutte contre la désinformation.</p>',NULL,NULL,35,1,3),
(17,11,'Briefing vidéo : la dimension humaine','video','<p>Les quatre principes qui guident toute collecte humaine légitime.</p>',NULL,5,4,1,1),
(18,11,'Les principes du HUMINT','text','<p>Toute collecte humaine repose sur une <strong>relation</strong> entre un professionnel et une personne qui accepte de partager ce qu''elle sait. Quatre principes structurent cette relation.</p>\n<h3>1. Le besoin d''en connaître</h3>\n<p>On ne recueille que ce qui répond à une question précise. Interroger « au cas où » expose inutilement les personnes et noie l''analyse.</p>\n<h3>2. Le consentement éclairé</h3>\n<p>Dans un cadre privé ou académique, la personne sait à qui elle parle, pourquoi, et ce que deviendront ses propos. Elle peut refuser de répondre ou retirer son accord.</p>\n<h3>3. La protection</h3>\n<p>Le professionnel est responsable de la sécurité et de la confidentialité de ses interlocuteurs. Une source exposée par négligence est une faute professionnelle grave.</p>\n<h3>4. Le scepticisme méthodique</h3>\n<p>La sympathie pour un interlocuteur ne doit jamais remplacer l''évaluation. Chaque information est recoupée.</p>\n<table><thead><tr><th>Profil d''interlocuteur</th><th>Apport typique</th><th>Vigilance</th></tr></thead><tbody>\n<tr><td>Expert académique</td><td>Analyse de fond, contexte historique</td><td>Biais d''école de pensée</td></tr>\n<tr><td>Acteur économique local</td><td>Réalités du terrain, prix, flux</td><td>Intérêts commerciaux</td></tr>\n<tr><td>Responsable associatif</td><td>Perception des populations</td><td>Engagement militant</td></tr>\n<tr><td>Fonctionnaire (propos publics)</td><td>Position officielle</td><td>Communication institutionnelle</td></tr>\n</tbody></table>',NULL,NULL,25,1,2),
(19,12,'Cadre juridique de la collecte','text','<p>La légalité de la collecte dépend à la fois <strong>du statut de celui qui collecte</strong> (service de l''État, entreprise, chercheur, journaliste) et <strong>des moyens employés</strong>.</p>\n<h3>Textes de référence (à adapter au pays d''exercice)</h3>\n<ul>\n<li>Constitutions nationales : droit à la vie privée, secret des correspondances.</li>\n<li>Lois nationales sur la protection des données personnelles et autorités de contrôle associées.</li>\n<li>Convention de l''Union africaine sur la cybersécurité et la protection des données à caractère personnel (Convention de Malabo, 2014).</li>\n<li>Code pénal : corruption, atteinte au secret professionnel, usurpation d''identité, intrusion.</li>\n<li>Droit du travail et secret des affaires.</li>\n</ul>\n<h3>Les lignes rouges absolues</h3>\n<div class="warning"><ul class="mb-0"><li>Offrir un avantage pour obtenir une information confidentielle (corruption) ;</li><li>Menacer, faire pression, exploiter une vulnérabilité (chantage, abus de faiblesse) ;</li><li>Usurper une identité ou une qualité (se dire policier, journaliste, auditeur…) ;</li><li>Enregistrer une conversation privée à l''insu de l''interlocuteur lorsque la loi l''interdit ;</li><li>Inciter quelqu''un à violer son obligation de confidentialité.</li></ul></div>\n<h3>Le test des quatre questions</h3>\n<ol><li>Est-ce légal dans le pays concerné ?</li><li>Serais-je à l''aise si la méthode était rendue publique ?</li><li>L''interlocuteur aurait-il accepté s''il avait su ?</li><li>Le bénéfice attendu justifie-t-il le risque pour les personnes ?</li></ol>\n<p>Une seule réponse négative suffit à abandonner la démarche.</p>',NULL,NULL,25,1,1),
(20,13,'L''entretien d''information','text','<p>L''entretien d''information est une conversation <strong>préparée, transparente et structurée</strong>. Il s''inspire des méthodes du journalisme et des sciences sociales.</p>\n<h3>Préparation</h3>\n<ul><li>Objectif écrit en une phrase ;</li><li>Recherche préalable sur le sujet (pour poser des questions intelligentes) ;</li><li>Guide d''entretien : 5 à 8 questions ouvertes, du général au particulier ;</li><li>Logistique : lieu neutre et confortable, durée annoncée.</li></ul>\n<h3>Conduite : la méthode de l''entonnoir</h3>\n<ol><li><strong>Accueil</strong> : présentation, finalité, règles de confidentialité, accord sur la prise de notes.</li><li><strong>Questions ouvertes</strong> : « Comment décririez-vous… ? », « Que s''est-il passé ensuite ? »</li><li><strong>Approfondissement</strong> : reformulation, relances neutres, demandes d''exemples.</li><li><strong>Questions fermées</strong> de vérification : dates, chiffres, noms publics.</li><li><strong>Clôture</strong> : « Y a-t-il un point que je n''ai pas abordé ? », remerciements.</li></ol>\n<h3>Écoute active</h3>\n<p>Silence accueillant, reformulation, attention au non-verbal, absence de jugement. On évite les questions suggestives (« Vous êtes d''accord que… ? ») qui contaminent la réponse.</p>\n<h3>Observation non intrusive</h3>\n<p>Observer un <strong>espace public</strong> (marché, gare, salon professionnel) permet de comprendre des flux, des usages, une ambiance — sans jamais suivre, photographier ou ficher des individus. On note des tendances (affluence, horaires, types d''activités), pas des identités.</p>\n<div class="note">Après l''entretien, rédigez votre compte rendu dans l''heure : la mémoire se dégrade très vite. Distinguez verbatim, paraphrase et impressions personnelles.</div>',NULL,NULL,30,1,1),
(21,14,'Coter une source et une information','text','<p>Le système de cotation le plus répandu, souvent appelé <strong>code de l''Amirauté</strong> ou système OTAN, évalue séparément <strong>la source</strong> (lettre) et <strong>l''information</strong> (chiffre).</p>\n<table><thead><tr><th>Fiabilité de la source</th><th>Crédibilité de l''information</th></tr></thead><tbody>\n<tr><td>A — Totalement fiable</td><td>1 — Confirmée par d''autres sources</td></tr>\n<tr><td>B — Habituellement fiable</td><td>2 — Probablement vraie</td></tr>\n<tr><td>C — Assez fiable</td><td>3 — Possiblement vraie</td></tr>\n<tr><td>D — Pas toujours fiable</td><td>4 — Douteuse</td></tr>\n<tr><td>E — Non fiable</td><td>5 — Improbable</td></tr>\n<tr><td>F — Fiabilité impossible à évaluer</td><td>6 — Véracité impossible à évaluer</td></tr>\n</tbody></table>\n<p>Une source habituellement fiable peut transmettre une information douteuse (B4), et une source inconnue une information confirmée (F1). C''est tout l''intérêt de la double cotation.</p>\n<h3>Critères d''évaluation de la source</h3>\n<ul><li><strong>Accès</strong> : était-elle en position de savoir ?</li><li><strong>Historique</strong> : ses informations passées se sont-elles vérifiées ?</li><li><strong>Motivation</strong> : quel intérêt a-t-elle à parler ?</li><li><strong>Cohérence</strong> interne du récit.</li></ul>\n<h3>Signaux d''alerte</h3>\n<ul><li>Information trop parfaite, qui répond exactement à ce que l''on espérait ;</li><li>Détails invérifiables abondants, précision factice ;</li><li>Pression pour une décision rapide ;</li><li>Sources multiples qui partagent en réalité une même origine (<em>rapport circulaire</em>).</li></ul>',NULL,NULL,25,1,1),
(22,15,'Fiche de synthèse (PDF)','document','<p>Guide d''entretien type, grille de cotation et test des quatre questions.</p>',NULL,6,10,1,1),
(23,15,'Exercice : préparer un guide d''entretien','exercise','<p><strong>Situation fictive.</strong> Une ONG de développement souhaite comprendre pourquoi un marché agricole régional a perdu la moitié de sa fréquentation en un an. Vous allez rencontrer, avec leur accord, un responsable de coopérative.</p>\n<h3>À produire</h3>\n<ol><li>L''objectif de l''entretien en une phrase.</li><li>Un texte d''introduction (présentation, finalité, confidentialité).</li><li>Six questions ouvertes ordonnées en entonnoir.</li><li>Trois relances neutres.</li><li>Un modèle de compte rendu distinguant verbatim, paraphrase et impressions.</li></ol>\n<div class="note">Critères d''évaluation : absence de questions suggestives, transparence sur la finalité, pertinence des relances, respect de la confidentialité.</div>',NULL,NULL,40,1,2),
(24,15,'Étude de cas : la source trop parfaite','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un cabinet d''analyse reçoit d''un contact rencontré récemment des informations très détaillées annonçant la faillite imminente d''un concurrent de son client. Le contact insiste pour que l''information soit utilisée « dans les 48 heures ».</p>\n<h3>Questions</h3>\n<ol><li>Quelle cotation provisoire attribuez-vous à la source et à l''information ? Justifiez.</li><li>Listez les signaux d''alerte présents.</li><li>Quelles vérifications ouvertes et légales mèneriez-vous (registres de commerce, publications légales, résultats financiers publiés) ?</li><li>Quels risques juridiques le client encourt-il s''il agit sur cette base (diffusion de fausses informations, manipulation de marché) ?</li></ol>\n<p><strong>Dénouement :</strong> l''information était une tentative de manipulation destinée à pousser le client à une communication publique préjudiciable. La prudence méthodique a protégé le client.</p>',NULL,NULL,30,1,3),
(25,16,'Briefing vidéo : protéger, interpréter, écrire','video','<p>Les trois piliers de la formation en un coup d''œil.</p>',NULL,7,4,1,1),
(26,16,'Protéger ses sources','text','<p>La protection des sources est un principe partagé par le renseignement, le journalisme (consacré par de nombreuses législations africaines sur la presse) et la recherche en sciences sociales. Elle repose sur trois mécanismes.</p>\n<h3>1. La pseudonymisation</h3>\n<p>Dans les documents de travail, la source est désignée par un code (ex. <code>S-014</code>). La table de correspondance est conservée séparément, avec un accès restreint.</p>\n<h3>2. Le cloisonnement</h3>\n<p>Seules les personnes qui en ont besoin connaissent l''identité d''une source. Les rapports diffusés décrivent l''<em>accès</em> de la source (« une personne ayant une connaissance directe du secteur ») sans permettre de l''identifier.</p>\n<h3>3. L''hygiène numérique</h3>\n<ul><li>Messageries chiffrées de bout en bout pour les échanges ;</li><li>Chiffrement des supports (ordinateurs, clés USB) ;</li><li>Attention aux métadonnées des fichiers et des photos ;</li><li>Politique de conservation : supprimer ce qui n''est plus nécessaire.</li></ul>\n<div class="warning"><strong>Risque de recoupement.</strong> Même sans nom, un détail (fonction rare, lieu, date d''une réunion à trois participants) peut suffire à identifier quelqu''un. Relisez chaque rapport avec ce regard.</div>',NULL,NULL,25,1,2),
(27,17,'Mythes et réalités du comportement','text','<p>Films et séries ont popularisé l''idée qu''un regard fuyant ou un geste de la main trahirait le mensonge. <strong>La recherche scientifique contredit largement ces croyances.</strong></p>\n<h3>Ce que montrent les études</h3>\n<ul><li>Les méta-analyses de la recherche en psychologie montrent que la capacité moyenne à détecter le mensonge à partir du comportement dépasse à peine le hasard (de l''ordre de 54 %).</li><li>Il n''existe <strong>aucun indice non verbal universel</strong> du mensonge, à la manière du « nez de Pinocchio ».</li><li>Le stress d''une personne honnête soupçonnée peut produire les mêmes signes que ceux attribués aux menteurs.</li><li>Les variations culturelles du contact visuel, de la gestuelle ou des silences sont considérables — un point crucial sur un continent aussi divers que l''Afrique.</li></ul>\n<h3>Ce qui fonctionne mieux</h3>\n<ul><li>Les approches centrées sur le <strong>contenu verbal</strong> : richesse en détails vérifiables, cohérence, plausibilité ;</li><li>La <strong>vérification factuelle</strong> des éléments avancés ;</li><li>Les entretiens non accusatoires, qui favorisent un récit libre et détaillé.</li></ul>\n<div class="warning">Ne jamais fonder un jugement sur une personne (recrutement, soupçon, sanction) à partir d''une « lecture » du comportement. C''est scientifiquement infondé et potentiellement discriminatoire.</div>',NULL,NULL,30,1,1),
(28,18,'Écrire pour un décideur','text','<p>Un décideur dispose de peu de temps. Le rapport doit lui permettre de comprendre <strong>l''essentiel en trente secondes</strong>, puis d''approfondir s''il le souhaite.</p>\n<h3>La structure BLUF</h3>\n<p><em>Bottom Line Up Front</em> : la conclusion d''abord.</p>\n<ol><li><strong>Titre-jugement</strong> : une phrase qui dit l''essentiel (« La hausse des prix du transport devrait se poursuivre jusqu''en mars »).</li><li><strong>Résumé</strong> en trois à cinq lignes, avec niveau de confiance.</li><li><strong>Développement</strong> : faits, analyse, hypothèses alternatives.</li><li><strong>Lacunes et indicateurs</strong> à surveiller.</li><li><strong>Sources</strong> et cotations.</li></ol>\n<h3>Règles d''écriture</h3>\n<ul><li>Phrases courtes, voix active, un paragraphe = une idée ;</li><li>Vocabulaire de probabilité normalisé (presque certain, probable, possible…) ;</li><li>Distinction visible entre faits et jugements ;</li><li>Pas d''adjectifs dramatiques ni de jargon inutile.</li></ul>\n<table><thead><tr><th>À éviter</th><th>À privilégier</th></tr></thead><tbody>\n<tr><td>« La situation est explosive. »</td><td>« Trois incidents ont été signalés en une semaine contre un par mois en moyenne ; une escalade est possible (confiance faible). »</td></tr>\n<tr><td>« Il semblerait que peut-être… »</td><td>« Il est probable que… »</td></tr>\n</tbody></table>',NULL,NULL,30,1,1),
(29,19,'Fiche de synthèse (PDF)','document','<p>Modèle de rapport BLUF, check-list de protection des sources et rappels scientifiques.</p>',NULL,8,10,1,1),
(30,19,'Exercice : rédiger un rapport BLUF','exercise','<p>À partir des éléments fictifs ci-dessous, rédigez un rapport d''une page.</p>\n<ul><li>Fait 1 : le prix du carburant a augmenté de 18 % en deux mois dans la région (statistiques officielles).</li><li>Fait 2 : deux syndicats de transporteurs ont annoncé publiquement des consultations de leurs membres.</li><li>Fait 3 : un responsable de coopérative (source cotée B, information cotée 3) évoque un possible mouvement de grève.</li><li>Lacune : aucune date n''est connue.</li></ul>\n<h3>Consignes</h3>\n<ol><li>Un titre-jugement.</li><li>Un résumé de quatre lignes avec niveau de confiance.</li><li>Deux hypothèses alternatives.</li><li>Trois indicateurs à surveiller.</li><li>La source humaine décrite sans pouvoir être identifiée.</li></ol>',NULL,NULL,50,1,2),
(31,19,'Étude de cas : la fuite par recoupement','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un rapport interne mentionne qu''« une source participant à la réunion restreinte du comité de direction du mardi » a signalé un projet de cession. Le rapport circule plus largement que prévu. En quelques heures, l''entreprise concernée identifie la source : seules quatre personnes assistaient à la réunion.</p>\n<h3>Questions</h3>\n<ol><li>Quelles erreurs de rédaction ont rendu l''identification possible ?</li><li>Réécrivez la mention de la source de manière protectrice.</li><li>Quelles mesures de diffusion auraient limité le risque ?</li><li>Quelles sont les responsabilités morales et juridiques de l''analyste ?</li></ol>',NULL,NULL,30,1,3),
(32,20,'Briefing vidéo : penser comme un défenseur','video','<p>Les principes de la posture défensive en contre-espionnage.</p>',NULL,9,4,1,1),
(33,20,'Comprendre l''ingérence','text','<p>Le contre-espionnage regroupe l''ensemble des mesures visant à <strong>détecter, prévenir et neutraliser</strong> les activités de renseignement hostiles dirigées contre une organisation ou un État. Pour une organisation privée, il s''agit essentiellement de <strong>protection</strong> et de <strong>vigilance</strong> ; les enquêtes et sanctions relèvent des autorités judiciaires.</p>\n<h3>Qui cherche à obtenir vos informations ?</h3>\n<ul><li>Des <strong>concurrents</strong> peu scrupuleux (intelligence économique offensive illégale) ;</li><li>Des <strong>acteurs étatiques</strong> étrangers intéressés par des secteurs stratégiques (mines, énergie, télécoms, agriculture) ;</li><li>Des <strong>groupes criminels</strong> (fraude, rançongiciels, extorsion) ;</li><li>Des <strong>individus</strong> motivés par la vengeance, l''idéologie ou l''argent.</li></ul>\n<h3>Les modes opératoires classiques</h3>\n<table><thead><tr><th>Vecteur</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Approche humaine</td><td>Faux recruteur, consultant trop curieux, stagiaire sans encadrement</td></tr>\n<tr><td>Numérique</td><td>Hameçonnage ciblé, compromission de messagerie</td></tr>\n<tr><td>Physique</td><td>Vol d''ordinateur en déplacement, documents laissés en salle de réunion</td></tr>\n<tr><td>Légal mais déloyal</td><td>Questions insistantes lors d''audits, de salons, de visites de site</td></tr>\n</tbody></table>\n<p>La plupart des pertes d''informations ne résultent pas d''opérations sophistiquées mais d''<strong>imprudences ordinaires</strong> : conversations dans un avion, publications sur les réseaux sociaux, mots de passe partagés.</p>',NULL,NULL,25,1,2),
(34,21,'La menace interne','text','<p>La menace interne désigne le risque qu''une personne disposant d''un <strong>accès légitime</strong> (salarié, prestataire, partenaire) cause un préjudice, volontairement ou non.</p>\n<h3>Trois profils</h3>\n<ul><li><strong>Négligent</strong> : le plus fréquent — erreur, méconnaissance des règles ;</li><li><strong>Compromis</strong> : ses identifiants ou son poste sont utilisés par un tiers ;</li><li><strong>Malveillant</strong> : agit intentionnellement, souvent après une frustration non traitée.</li></ul>\n<h3>Facteurs de risque organisationnels</h3>\n<ul><li>Droits d''accès excessifs et jamais révisés ;</li><li>Départs mal gérés (comptes actifs après la fin du contrat) ;</li><li>Climat social dégradé, absence de canal d''écoute ;</li><li>Absence de séparation des tâches sensibles.</li></ul>\n<h3>Mesures proportionnées</h3>\n<ol><li><strong>Moindre privilège</strong> : chacun n''accède qu''à ce dont il a besoin ;</li><li><strong>Revue périodique</strong> des accès ;</li><li><strong>Procédures d''arrivée et de départ</strong> formalisées ;</li><li><strong>Culture de confiance</strong> : un canal de signalement protégé et un management attentif réduisent davantage le risque que la surveillance.</li></ol>\n<div class="warning">La surveillance des salariés est strictement encadrée par le droit du travail et la protection des données : information préalable, proportionnalité, finalité légitime. Une surveillance généralisée détruit la confiance et peut être illégale.</div>',NULL,NULL,25,1,1),
(35,22,'Classifier et protéger','text','<p>On ne peut pas tout protéger avec la même intensité. La démarche commence par l''identification du <strong>patrimoine informationnel critique</strong> : ce dont la perte, l''altération ou la divulgation causerait un préjudice grave.</p>\n<h3>Étape 1 : inventaire</h3>\n<p>Pour chaque information sensible : qui la détient, où est-elle stockée, qui y accède, quelle serait la conséquence d''une fuite ?</p>\n<h3>Étape 2 : une classification simple</h3>\n<table><thead><tr><th>Niveau</th><th>Exemples</th><th>Règles</th></tr></thead><tbody>\n<tr><td>Public</td><td>Plaquette, site web</td><td>Diffusion libre</td></tr>\n<tr><td>Interne</td><td>Notes de service, organigramme</td><td>Personnels uniquement</td></tr>\n<tr><td>Confidentiel</td><td>Offres commerciales, données RH</td><td>Liste nominative, chiffrement</td></tr>\n<tr><td>Secret organisationnel</td><td>Stratégie, négociations en cours</td><td>Accès très restreint, traçabilité</td></tr>\n</tbody></table>\n<h3>Étape 3 : mesures</h3>\n<ul><li>Marquage visible des documents ;</li><li>Chiffrement des fichiers et des supports ;</li><li>Bureau et écran propres ; destruction sécurisée des papiers ;</li><li>Règles de discussion en lieux publics et en déplacement ;</li><li>Clauses de confidentialité avec les partenaires.</li></ul>\n<div class="callout">Une classification trop complexe n''est pas appliquée. Quatre niveaux suffisent dans la plupart des organisations.</div>',NULL,NULL,25,1,1),
(36,23,'Reconnaître la manipulation','text','<p>L''ingénierie sociale exploite des réflexes humains normaux — serviabilité, respect de l''autorité, peur — pour obtenir une information ou une action. Elle précède la majorité des cyberattaques réussies.</p>\n<h3>Les leviers utilisés</h3>\n<table><thead><tr><th>Levier</th><th>Formulation typique</th></tr></thead><tbody>\n<tr><td>Autorité</td><td>« Le directeur général exige ce virement aujourd''hui. »</td></tr>\n<tr><td>Urgence</td><td>« Votre compte sera bloqué dans une heure. »</td></tr>\n<tr><td>Sympathie</td><td>« On s''est croisés au séminaire de Dakar, tu te souviens ? »</td></tr>\n<tr><td>Réciprocité</td><td>Petit cadeau ou service rendu, puis demande</td></tr>\n<tr><td>Preuve sociale</td><td>« Tous vos collègues ont déjà validé. »</td></tr>\n</tbody></table>\n<h3>Scénarios fréquents en Afrique</h3>\n<ul><li>Fraude au président par messagerie instantanée ou appel vocal ;</li><li>Faux changement de coordonnées bancaires d''un fournisseur ;</li><li>Fausses offres d''emploi ou de bourses visant les jeunes diplômés ;</li><li>Faux techniciens d''opérateurs télécoms ou de services de paiement mobile.</li></ul>\n<h3>Parades</h3>\n<ol><li><strong>Vérifier par un autre canal</strong> (rappeler un numéro connu, jamais celui fourni) ;</li><li>Ne jamais céder à l''urgence artificielle : <em>« ralentir, c''est se protéger »</em> ;</li><li>Procédures de double validation pour les paiements ;</li><li>Signaler sans crainte : celui qui signale une tentative ne doit jamais être blâmé.</li></ol>',NULL,NULL,25,1,1),
(37,24,'Fiche de synthèse (PDF)','document','<p>Grille de classification, check-list anti-ingénierie sociale et procédure de signalement type.</p>',NULL,10,10,1,1),
(38,24,'Exercice : cartographier les actifs sensibles','exercise','<p><strong>Organisation fictive :</strong> « AgroSahel Coop », coopérative de 40 salariés qui exporte des produits transformés et prépare une levée de fonds.</p>\n<h3>Consignes</h3>\n<ol><li>Identifiez huit actifs informationnels (recettes, fichier clients, négociation financière, données RH…).</li><li>Classez-les selon la grille à quatre niveaux.</li><li>Pour les trois plus critiques, indiquez qui y accède aujourd''hui et qui <em>devrait</em> y accéder.</li><li>Proposez cinq mesures prioritaires, réalistes pour une PME.</li></ol>',NULL,NULL,45,1,2),
(39,24,'Étude de cas : la fraude au fournisseur','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une société de BTP reçoit un courriel apparemment envoyé par son principal fournisseur annonçant un changement de banque. Le comptable met à jour les coordonnées. Deux virements importants partent vers le compte frauduleux avant que le vrai fournisseur ne réclame son paiement.</p>\n<h3>Questions</h3>\n<ol><li>Quels indices auraient dû alerter (domaine de l''adresse, ton, timing) ?</li><li>Quelle procédure de contrôle aurait empêché la fraude ?</li><li>Qui prévenir immédiatement après la découverte (banque, autorités, plateforme de signalement nationale) ?</li><li>Comment communiquer en interne sans désigner de coupable ?</li></ol>',NULL,NULL,30,1,3),
(40,25,'Briefing vidéo : la sécurité comme système','video','<p>Vue d''ensemble des couches de sécurité d''une organisation.</p>',NULL,11,4,1,1),
(41,25,'Protéger les personnes','text','<p>Les personnes sont à la fois la première ressource et la première cible. La sécurité du personnel couvre le cycle de vie professionnel et les situations de déplacement.</p>\n<h3>Le cycle de vie</h3>\n<ul><li><strong>Recrutement</strong> : vérifications proportionnées et légales (diplômes, références), sans enquête intrusive sur la vie privée ;</li><li><strong>Intégration</strong> : sensibilisation, charte, signature des engagements de confidentialité ;</li><li><strong>En poste</strong> : formation continue, entretiens réguliers ;</li><li><strong>Départ</strong> : restitution des équipements, clôture des accès, rappel des obligations.</li></ul>\n<h3>Sécurité en déplacement</h3>\n<table><thead><tr><th>Avant</th><th>Pendant</th><th>Après</th></tr></thead><tbody>\n<tr><td>Analyse du pays (avis officiels), itinéraire, contacts d''urgence, équipement informatique dédié</td><td>Discrétion, points de contact réguliers, vigilance sur les réseaux Wi-Fi publics</td><td>Débriefing, signalement d''incidents, contrôle des appareils</td></tr>\n</tbody></table>\n<div class="callout">Le devoir de protection de l''employeur (<em>duty of care</em>) impose d''évaluer les risques avant d''envoyer un collaborateur en mission et de prévoir les moyens d''assistance.</div>',NULL,NULL,25,1,2),
(42,26,'Conduire une analyse de menaces','text','<p>Le risque résulte de la combinaison d''une <strong>menace</strong> (un acteur avec une intention et une capacité), d''une <strong>vulnérabilité</strong> (une faiblesse exploitable) et d''un <strong>impact</strong> (la gravité des conséquences).</p>\n<h3>Évaluer une menace</h3>\n<ul><li><strong>Intention</strong> : l''acteur veut-il nous nuire ? Pourquoi ?</li><li><strong>Capacité</strong> : en a-t-il les moyens ?</li><li><strong>Opportunité</strong> : nos vulnérabilités lui offrent-elles une ouverture ?</li></ul>\n<h3>La matrice probabilité × impact</h3>\n<table><thead><tr><th></th><th>Impact faible</th><th>Impact modéré</th><th>Impact grave</th></tr></thead><tbody>\n<tr><th>Probable</th><td>Moyen</td><td>Élevé</td><td><strong>Critique</strong></td></tr>\n<tr><th>Possible</th><td>Faible</td><td>Moyen</td><td>Élevé</td></tr>\n<tr><th>Peu probable</th><td>Faible</td><td>Faible</td><td>Moyen</td></tr>\n</tbody></table>\n<h3>Sources d''information sur les menaces</h3>\n<p>Rapports publics d''autorités nationales de cybersécurité, bulletins des équipes CERT/CSIRT africaines, alertes sectorielles, retours d''expérience des pairs, incidents internes. L''analyse doit être <strong>actualisée régulièrement</strong> : une matrice figée devient trompeuse.</p>',NULL,NULL,30,1,1),
(43,27,'Choisir des contre-mesures','text','<p>Une contre-mesure réduit la probabilité ou l''impact d''un risque. La défense efficace est <strong>en profondeur</strong> : plusieurs couches complémentaires, de sorte qu''une défaillance isolée ne suffise pas.</p>\n<h3>Les quatre fonctions</h3>\n<ol><li><strong>Prévenir</strong> : contrôle d''accès, chiffrement, formation, procédures ;</li><li><strong>Détecter</strong> : journalisation, alertes, signalements des personnels ;</li><li><strong>Réagir</strong> : plan de réponse, cellule de crise, contacts juridiques et autorités ;</li><li><strong>Se rétablir</strong> : sauvegardes testées, plan de continuité, retour d''expérience.</li></ol>\n<h3>Prioriser</h3>\n<p>Chaque mesure est évaluée selon son coût, sa facilité de mise en œuvre et sa réduction du risque. Les mesures « à fort effet et faible coût » viennent en premier : double authentification, sauvegardes hors ligne, procédure de contre-appel pour les paiements, sensibilisation.</p>\n<div class="note"><strong>Contre-mesures et droit :</strong> les mesures défensives restent dans le périmètre de l''organisation. « Riposter » contre un attaquant (intrusion en retour, représailles) est illégal et dangereux : on signale aux autorités compétentes.</div>',NULL,NULL,25,1,1),
(44,28,'Concevoir un exercice sur table','text','<p>L''exercice sur table (<em>tabletop exercise</em>) réunit les décideurs autour d''un scénario fictif qui se déroule par étapes (« injects »). Il teste les procédures, la coordination et la communication sans aucun risque réel.</p>\n<h3>Conception en cinq étapes</h3>\n<ol><li>Définir 2 ou 3 objectifs (ex. tester la chaîne d''alerte) ;</li><li>Écrire un scénario plausible et <strong>entièrement fictif</strong> ;</li><li>Préparer 5 à 8 injects successifs ;</li><li>Désigner un animateur et un observateur ;</li><li>Prévoir un débriefing structuré : ce qui a fonctionné, ce qui doit changer, qui fait quoi et quand.</li></ol>\n<div class="callout">Un exercice réussi n''est pas un exercice sans erreurs : c''est un exercice qui révèle les failles avant qu''une vraie crise ne le fasse.</div>',NULL,NULL,25,1,1),
(45,29,'Fiche de synthèse (PDF)','document','<p>Modèles de matrice de risques, de plan de déplacement et de fiche d''exercice.</p>',NULL,12,10,1,1),
(46,29,'Exercice : matrice de risques','exercise','<p><strong>Organisation fictive :</strong> une université régionale qui héberge un laboratoire de recherche sur les semences résistantes à la sécheresse.</p>\n<ol><li>Identifiez six risques (fuite de résultats, rançongiciel, vol de matériel, ingérence via partenariats…).</li><li>Évaluez chacun : intention, capacité, vulnérabilité, impact.</li><li>Placez-les dans la matrice.</li><li>Proposez deux contre-mesures par risque critique, classées par coût.</li></ol>',NULL,NULL,45,1,2),
(47,29,'Étude de cas : exercice « Harmattan »','case_study','<p><strong>Simulation pédagogique (fictive).</strong> Un groupe logistique découvre un lundi matin que ses serveurs sont chiffrés par un rançongiciel, en pleine période de dédouanement.</p>\n<ul><li><strong>Inject 1 (08 h 10)</strong> : les agents ne peuvent plus imprimer les déclarations.</li><li><strong>Inject 2 (09 h 00)</strong> : une demande de rançon apparaît ; les attaquants menacent de publier des données clients.</li><li><strong>Inject 3 (10 h 30)</strong> : un journaliste appelle le service communication.</li><li><strong>Inject 4 (12 h 00)</strong> : on découvre que la dernière sauvegarde hors ligne date de trois semaines.</li></ul>\n<h3>Questions de débriefing</h3>\n<ol><li>Qui aurait dû être alerté, dans quel ordre ?</li><li>Quelles obligations de notification (autorité de protection des données, clients) s''appliquent ?</li><li>Pourquoi est-il déconseillé de payer la rançon ?</li><li>Quelles trois mesures auraient le plus réduit l''impact ?</li></ol>',NULL,NULL,40,1,3),
(48,30,'Briefing vidéo : le terrain numérique','video','<p>Panorama visuel des menaces numériques et de la posture de l''analyste.</p>',NULL,13,4,1,1),
(49,30,'Comprendre le cyberespionnage','text','<p>Le cyberespionnage désigne l''accès non autorisé à des systèmes d''information pour y dérober des données, de façon discrète et souvent prolongée. Il se distingue du cybercrime (motivation financière directe) et du sabotage (destruction), même si les frontières sont poreuses.</p>\n<h3>Les acteurs</h3>\n<ul><li>Groupes liés à des États, souvent désignés par les éditeurs de sécurité sous le terme <strong>APT</strong> (<em>Advanced Persistent Threat</em>) ;</li><li>Mercenaires numériques et sociétés de surveillance commerciale ;</li><li>Groupes criminels revendant des accès.</li></ul>\n<h3>La chaîne d''attaque (modèle conceptuel)</h3>\n<ol><li>Reconnaissance (souvent en sources ouvertes) ;</li><li>Accès initial (hameçonnage ciblé, identifiants volés) ;</li><li>Installation et persistance ;</li><li>Mouvement latéral ;</li><li>Exfiltration.</li></ol>\n<p>Connaître cette chaîne sert à <strong>placer des défenses à chaque étape</strong> : moins d''informations exposées publiquement, authentification forte, détection des comportements anormaux, segmentation des réseaux, surveillance des flux sortants.</p>\n<div class="note">Le cadre de référence MITRE ATT&amp;CK, librement consultable, décrit de façon structurée les tactiques et techniques observées. Il est utilisé ici comme langage commun de défense.</div>',NULL,NULL,25,1,2),
(50,31,'Techniques de recherche avancées','text','<p>L''OSINT avancé se caractérise par la précision des requêtes, la capacité à <strong>pivoter</strong> d''un indice à l''autre et une rigoureuse hygiène opérationnelle.</p>\n<h3>Opérateurs de recherche</h3>\n<table><thead><tr><th>Opérateur</th><th>Usage</th><th>Exemple</th></tr></thead><tbody>\n<tr><td><code>site:</code></td><td>Limiter à un domaine</td><td><code>site:gouv.sn rapport annuel</code></td></tr>\n<tr><td><code>filetype:</code></td><td>Type de document</td><td><code>filetype:pdf budget santé 2025</code></td></tr>\n<tr><td><code>"…"</code></td><td>Expression exacte</td><td><code>"appel d''offres" "fibre optique"</code></td></tr>\n<tr><td><code>-</code></td><td>Exclure un terme</td><td><code>jaguar -voiture</code></td></tr>\n</tbody></table>\n<h3>Le pivot</h3>\n<p>Un indicateur en révèle d''autres : un nom de domaine mène à son historique d''enregistrement public, à ses certificats TLS (journaux de transparence), aux autres sites hébergés sur la même infrastructure. Chaque pivot est noté dans un journal d''enquête.</p>\n<h3>Hygiène de l''enquêteur</h3>\n<ul><li>Environnement de travail dédié et séparé de ses comptes personnels ;</li><li>Aucune interaction avec les cibles (pas de « like », pas de message, pas de demande d''ami) ;</li><li>Respect des conditions d''utilisation des plateformes ;</li><li>Collecte minimale de données personnelles.</li></ul>',NULL,NULL,30,1,1);
INSERT INTO `lessons` (`id`,`chapter_id`,`title`,`type`,`content`,`video_url`,`media_id`,`duration_minutes`,`is_downloadable`,`sort_order`) VALUES
(51,32,'Empreinte numérique organisationnelle','text','<p>L''empreinte numérique d''une organisation est l''ensemble des traces publiquement observables : sites, sous-domaines, adresses e-mail, profils des employés, documents publiés, dépôts de code, offres d''emploi détaillant les technologies utilisées…</p>\n<h3>Pourquoi l''analyser ?</h3>\n<p>Un attaquant commence par là. L''analyser <strong>pour sa propre organisation</strong> (ou pour un client qui l''a mandaté par écrit) permet de réduire la surface d''attaque.</p>\n<h3>Grille d''audit d''exposition</h3>\n<ul><li><strong>Domaines et sous-domaines</strong> : services oubliés, environnements de test exposés ;</li><li><strong>Documents publics</strong> : métadonnées révélant noms d''utilisateurs, versions logicielles ;</li><li><strong>Personnes</strong> : organigramme reconstituable, formats d''adresses e-mail ;</li><li><strong>Fuites</strong> : identifiants apparus dans des fuites publiques connues (à vérifier via des services de notification légitimes).</li></ul>\n<div class="warning">Un audit d''exposition sur une organisation tierce nécessite un <strong>mandat écrit</strong>. Sans autorisation, même une collecte « passive » peut poser problème juridiquement et déontologiquement.</div>',NULL,NULL,25,1,1),
(52,33,'Exploiter les métadonnées','text','<p>Les métadonnées sont des « données sur les données » : auteur d''un document, logiciel utilisé, dates de création et de modification, modèle d''appareil photo, parfois coordonnées GPS.</p>\n<h3>Types courants</h3>\n<table><thead><tr><th>Format</th><th>Métadonnées typiques</th></tr></thead><tbody>\n<tr><td>Photo (EXIF)</td><td>Appareil, date, réglages, éventuellement GPS</td></tr>\n<tr><td>PDF</td><td>Auteur, créateur, producteur, dates</td></tr>\n<tr><td>Bureautique</td><td>Auteur, dernier modificateur, révisions, commentaires</td></tr>\n</tbody></table>\n<h3>Précautions d''interprétation</h3>\n<ul><li>Les métadonnées peuvent être <strong>absentes</strong> (supprimées par les réseaux sociaux) ou <strong>falsifiées</strong> ;</li><li>L''horloge d''un appareil peut être mal réglée ;</li><li>Une métadonnée est un indice, jamais une preuve isolée.</li></ul>\n<h3>Préservation de la preuve</h3>\n<p>Dans un cadre d''enquête autorisée, on travaille sur une <strong>copie</strong>, on calcule l''<strong>empreinte cryptographique</strong> (SHA-256) de l''original et on consigne chaque manipulation (chaîne de traçabilité).</p>\n<div class="callout"><strong>Réflexe défensif :</strong> nettoyez les métadonnées des documents que votre organisation publie.</div>',NULL,NULL,25,1,1),
(53,34,'Fiche de synthèse (PDF)','document','<p>Opérateurs de recherche, grille d''audit d''exposition et procédure de préservation des fichiers.</p>',NULL,14,10,1,1),
(54,34,'Exercice : audit d''exposition d''une organisation fictive','exercise','<p><strong>Environnement :</strong> dossier de données synthétiques « Kilimanjaro Logistics » (organisation fictive) : liste de sous-domaines, trois documents PDF, cinq profils professionnels fictifs, une offre d''emploi.</p>\n<ol><li>Recensez toutes les informations exploitables par un attaquant.</li><li>Déduisez le format probable des adresses e-mail.</li><li>Identifiez les métadonnées sensibles des documents.</li><li>Classez les expositions par gravité.</li><li>Rédigez cinq recommandations de réduction de l''exposition.</li></ol>\n<div class="note">Toutes les données sont fictives. Ne transposez jamais l''exercice sur une organisation réelle sans mandat écrit.</div>',NULL,NULL,50,1,2),
(55,34,'Étude de cas : le document trop bavard','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un ministère publie en ligne un rapport PDF. Ses métadonnées révèlent le nom d''utilisateur réseau de l''auteur, la version d''un logiciel obsolète et le chemin d''un serveur interne. Quelques semaines plus tard, une campagne d''hameçonnage très ciblée vise précisément ce service.</p>\n<ol><li>Quelles informations ont pu servir à la reconnaissance ?</li><li>Quelle procédure de publication aurait évité la fuite ?</li><li>Comment sensibiliser les équipes de communication ?</li></ol>',NULL,NULL,30,1,3),
(56,35,'Briefing vidéo : de la donnée à la décision','video','<p>Les niveaux de la CTI et leurs destinataires.</p>',NULL,15,4,1,1),
(57,35,'Les fondamentaux de la CTI','text','<p>La CTI applique le cycle du renseignement au domaine cyber. Elle répond à des questions comme : <em>qui pourrait nous viser, comment, et que devons-nous surveiller ?</em></p>\n<h3>Trois niveaux</h3>\n<table><thead><tr><th>Niveau</th><th>Destinataire</th><th>Contenu</th></tr></thead><tbody>\n<tr><td>Stratégique</td><td>Direction</td><td>Tendances, acteurs, impacts métier</td></tr>\n<tr><td>Opérationnel</td><td>Responsables sécurité</td><td>Campagnes, modes opératoires (TTP)</td></tr>\n<tr><td>Tactique</td><td>SOC / équipes techniques</td><td>Indicateurs de compromission (IoC)</td></tr>\n</tbody></table>\n<h3>Le modèle en diamant</h3>\n<p>Chaque événement d''intrusion est décrit par quatre sommets reliés : <strong>adversaire</strong>, <strong>capacité</strong>, <strong>infrastructure</strong>, <strong>victime</strong>. Connaître un sommet permet de rechercher les autres.</p>\n<h3>La pyramide de la douleur</h3>\n<p>Bloquer une adresse IP gêne peu un attaquant (il en change facilement) ; détecter ses <strong>TTP</strong> (comportements) l''oblige à modifier ses méthodes, ce qui est beaucoup plus coûteux pour lui. La CTI vise donc le haut de la pyramide.</p>',NULL,NULL,30,1,2),
(58,36,'Comprendre une infrastructure','text','<p>Toute activité en ligne repose sur une infrastructure : noms de domaine, serveurs, adresses IP, certificats, hébergeurs. Ces éléments laissent des traces publiques exploitables légalement.</p>\n<h3>Sources ouvertes d''infrastructure</h3>\n<ul><li><strong>WHOIS / RDAP</strong> : informations d''enregistrement (souvent masquées) ;</li><li><strong>DNS historique</strong> : évolution des résolutions d''un domaine ;</li><li><strong>Journaux de transparence des certificats</strong> : certificats émis pour un domaine ;</li><li><strong>Moteurs d''exposition</strong> recensant les services visibles sur Internet ;</li><li><strong>Registres régionaux</strong> (AFRINIC pour l''Afrique) : attribution des blocs d''adresses.</li></ul>\n<h3>Exemple de raisonnement (données fictives)</h3>\n<p>Un domaine d''hameçonnage imitant une banque est hébergé sur une IP qui sert aussi trois autres domaines récemment enregistrés, imitant d''autres institutions financières. Hypothèse : une même campagne. Action : signalement aux CSIRT et aux registrars, alerte aux clients.</p>\n<div class="note">L''analyse d''infrastructure reste passive : on consulte des registres publics, on n''interagit pas avec les systèmes d''un tiers au-delà d''un usage normal.</div>',NULL,NULL,25,1,1),
(59,37,'Communiquer en sécurité','text','<p>Protéger ses communications est un droit et une nécessité professionnelle : journalistes, avocats, ONG, entreprises et administrations y sont confrontés.</p>\n<h3>Notions clés</h3>\n<ul><li><strong>Chiffrement en transit</strong> (TLS) : protège le trajet entre vous et le serveur ;</li><li><strong>Chiffrement de bout en bout</strong> : seuls l''émetteur et le destinataire peuvent lire ;</li><li><strong>Vérification des clés</strong> : comparer les codes de sécurité pour éviter l''interposition ;</li><li><strong>Métadonnées</strong> : même chiffrées, les communications révèlent qui parle à qui et quand.</li></ul>\n<h3>Bonnes pratiques</h3>\n<ol><li>Authentification multifacteur sur toutes les messageries professionnelles ;</li><li>Applications à jour, verrouillage des appareils ;</li><li>Messages éphémères pour les échanges sensibles ;</li><li>Séparation des usages personnels et professionnels ;</li><li>Prudence avec les réseaux Wi-Fi publics.</li></ol>\n<div class="callout">La sécurité d''une communication dépend du maillon le plus faible : un téléphone non verrouillé annule le meilleur chiffrement.</div>',NULL,NULL,25,1,1),
(60,38,'Détecter l''anomalie','text','<p>La détection consiste à repérer, dans le flux d''événements d''un système <strong>que l''on est autorisé à surveiller</strong>, ce qui s''écarte du comportement normal.</p>\n<h3>Signaux typiques dans les journaux d''authentification</h3>\n<ul><li>Nombreux échecs de connexion suivis d''un succès ;</li><li>Connexion depuis un pays inhabituel ou à une heure atypique ;</li><li>« Voyage impossible » : deux connexions éloignées géographiquement en peu de temps ;</li><li>Création de règles de transfert automatique dans une messagerie ;</li><li>Volume inhabituel de téléchargements.</li></ul>\n<h3>Extrait de journal synthétique</h3>\n<pre><code>2026-03-04 02:11:07 user=a.diallo  src=196.0.2.14  result=FAIL\n2026-03-04 02:11:09 user=a.diallo  src=196.0.2.14  result=FAIL\n2026-03-04 02:11:12 user=a.diallo  src=196.0.2.14  result=SUCCESS\n2026-03-04 02:14:40 user=a.diallo  action=create_forward_rule dest=external</code></pre>\n<p>Lecture : connexion nocturne après échecs, puis création d''une règle de transfert vers l''extérieur : scénario classique de compromission de messagerie. Réponse : suspendre la session, réinitialiser le mot de passe, supprimer la règle, enquêter sur l''étendue.</p>\n<div class="note">Une alerte n''est pas une preuve : il faut qualifier (vrai ou faux positif) avant d''agir, et documenter.</div>',NULL,NULL,30,1,1),
(61,39,'Fiche de synthèse (PDF)','document','<p>Modèle de rapport CTI, modèle en diamant et liste des signaux de détection.</p>',NULL,16,10,1,1),
(62,39,'Exercice : analyser un journal synthétique','exercise','<p>Le jeu de données fourni (fictif) contient 200 lignes d''authentification d''une organisation imaginaire sur une semaine.</p>\n<ol><li>Établissez le profil normal (horaires, origines, volumes).</li><li>Identifiez au moins trois anomalies et qualifiez-les.</li><li>Placez l''incident principal dans le modèle en diamant.</li><li>Associez les comportements observés à des techniques MITRE ATT&amp;CK.</li><li>Rédigez un rapport CTI tactique d''une page avec recommandations.</li></ol>\n<pre><code>2026-03-01 08:02:44 user=k.mensah src=41.0.0.21 result=SUCCESS\n2026-03-02 23:47:10 user=k.mensah src=203.0.113.9 result=SUCCESS\n2026-03-02 23:47:58 user=k.mensah action=mass_download files=412</code></pre>',NULL,NULL,50,1,2),
(63,39,'Étude de cas : campagne contre le secteur bancaire','case_study','<p><strong>Scénario pédagogique (fictif).</strong> En trois semaines, quatre banques d''une même zone monétaire signalent des courriels imitant leur autorité de régulation et contenant une pièce jointe piégée. Le CSIRT régional coordonne l''analyse.</p>\n<ol><li>Quelles informations partager entre banques, et sous quel format (niveau TLP) ?</li><li>Quels indicateurs tactiques et quels TTP retenir ?</li><li>Quel message stratégique adresser aux directions générales ?</li><li>Quelles mesures de sensibilisation des clients ?</li></ol>',NULL,NULL,35,1,3),
(64,40,'Briefing vidéo : la boîte à outils de l''analyste','video','<p>Panorama visuel des familles d''outils et de la règle d''or : mandat, légalité, proportionnalité.</p>',NULL,17,4,1,1),
(65,40,'Panorama des outils OSINT','text','<table><thead><tr><th>Outil</th><th>Fonction</th><th>Usage légitime type</th></tr></thead><tbody>\n<tr><td><strong>Maltego</strong></td><td>Visualisation de liens sous forme de graphe ; « transformations » interrogeant des sources</td><td>Cartographier les relations publiques entre entreprises et domaines dans une enquête de conformité</td></tr>\n<tr><td><strong>SpiderFoot</strong></td><td>Automatisation de la collecte ouverte autour d''un indicateur</td><td>Évaluer l''exposition de sa propre organisation</td></tr>\n<tr><td><strong>theHarvester</strong></td><td>Recensement d''adresses e-mail, sous-domaines et hôtes publics</td><td>Audit de surface d''attaque mandaté</td></tr>\n<tr><td><strong>Recon-ng</strong></td><td>Cadre modulaire de reconnaissance en ligne de commande</td><td>Industrialiser une collecte ouverte documentée</td></tr>\n<tr><td><strong>Shodan</strong></td><td>Moteur recensant les services exposés sur Internet</td><td>Repérer ses propres équipements exposés par erreur ; études statistiques</td></tr>\n<tr><td><strong>Google Earth</strong></td><td>Imagerie et historique géographique</td><td>Géolocalisation, suivi environnemental, préparation logistique</td></tr>\n</tbody></table>\n<h3>Bonnes pratiques communes</h3>\n<ul><li>Respecter les conditions d''utilisation et les licences ;</li><li>Ne fournir aux outils que les clés d''API légitimement obtenues ;</li><li>Limiter la collecte de données personnelles au strict nécessaire ;</li><li>Conserver un journal des requêtes pour la traçabilité.</li></ul>\n<div class="warning">Ces outils ne doivent jamais servir à profiler, suivre ou harceler une personne privée. Un tel usage peut constituer une infraction (atteinte à la vie privée, harcèlement) et viole la charte AFRICA''SPY.</div>',NULL,NULL,30,1,2),
(66,41,'Analyse réseau et forensique','text','<h3>Wireshark — analyse de protocoles</h3>\n<p>Wireshark capture et décode le trafic d''un réseau. Usage légitime : diagnostiquer une panne, comprendre un protocole, analyser une capture fournie dans un cadre pédagogique ou d''incident. <strong>Capturer le trafic d''un réseau dont on n''est pas responsable est illégal.</strong></p>\n<h3>Autopsy — investigation de supports</h3>\n<p>Interface graphique d''investigation de disques : chronologie des fichiers, recherche par mots-clés, récupération d''éléments supprimés, extraction de métadonnées. Utilisé par les enquêteurs autorisés et les équipes de réponse à incident, sur des <strong>copies</strong> de supports.</p>\n<h3>Volatility — analyse de la mémoire vive</h3>\n<p>Cadre d''analyse d''images mémoire : processus actifs, connexions, artefacts de logiciels malveillants. Indispensable en réponse à incident, car certaines menaces ne laissent aucune trace sur disque.</p>\n<h3>Principes de l''investigation numérique</h3>\n<ol><li><strong>Mandat</strong> : autorisation écrite ou cadre judiciaire ;</li><li><strong>Préservation</strong> : copie bit à bit, empreinte cryptographique ;</li><li><strong>Traçabilité</strong> : chaîne de possession documentée ;</li><li><strong>Reproductibilité</strong> : un autre expert doit aboutir aux mêmes constats ;</li><li><strong>Neutralité</strong> : rechercher les éléments à charge comme à décharge.</li></ol>',NULL,NULL,30,1,1),
(67,42,'Les équipements de l''analyste de terrain','text','<table><thead><tr><th>Équipement</th><th>Usage légitime</th><th>Limites et règles</th></tr></thead><tbody>\n<tr><td>Jumelles d''observation</td><td>Observation de paysages, de sites publics, d''infrastructures, études environnementales</td><td>Jamais vers des espaces privés ni pour suivre une personne</td></tr>\n<tr><td>Appareil photo professionnel</td><td>Documentation de sites, reportage, constat</td><td>Droit à l''image, interdictions de photographier certains sites sensibles</td></tr>\n<tr><td>GPS de navigation</td><td>Orientation, relevés de terrain, sécurité des missions</td><td>Ne jamais poser de traceur sur un bien d''autrui</td></tr>\n<tr><td>Communications sécurisées</td><td>Liaison des équipes, coordination de crise</td><td>Respect des réglementations radio nationales</td></tr>\n<tr><td>Station d''analyse numérique</td><td>Traitement de données, forensique autorisée</td><td>Isolement, chiffrement, contrôle d''accès</td></tr>\n<tr><td>Protection des documents</td><td>Coffres, broyeurs, sacoches sécurisées</td><td>Adaptés au niveau de classification</td></tr>\n</tbody></table>\n<div class="warning">L''Académie ne fournit aucun plan de fabrication, aucune information sur des dispositifs clandestins (micros, traceurs dissimulés) ni aucune méthode d''interception. Leur usage par des particuliers est illégal dans la plupart des pays.</div>',NULL,NULL,25,1,1),
(68,43,'Avant d''utiliser un outil','text','<p>Le professionnel rédige, avant toute investigation, une <strong>note de cadrage</strong> qui répond à six questions :</p>\n<ol><li><strong>Finalité</strong> : quelle question précise ?</li><li><strong>Mandat</strong> : qui autorise, par écrit ?</li><li><strong>Périmètre</strong> : quelles cibles, quelles exclusions ?</li><li><strong>Base légale</strong> : quelles lois s''appliquent (données personnelles, cybercriminalité) ?</li><li><strong>Proportionnalité</strong> : l''outil choisi est-il le moins intrusif possible ?</li><li><strong>Conservation</strong> : combien de temps garde-t-on les données, et comment les détruit-on ?</li></ol>\n<p>Cette discipline protège les personnes concernées, le client et l''analyste lui-même.</p>',NULL,NULL,20,1,1),
(69,44,'Fiche de synthèse (PDF)','document','<p>Tableau des outils, usages légitimes et modèle de note de cadrage.</p>',NULL,18,10,1,1),
(70,44,'Exercice : rédiger une note de cadrage','exercise','<p><strong>Mandat fictif :</strong> une banque régionale vous charge par écrit d''évaluer l''exposition publique de ses propres services en ligne.</p>\n<ol><li>Rédigez la note de cadrage en six rubriques.</li><li>Sélectionnez trois outils et justifiez chaque choix.</li><li>Listez explicitement ce qui est hors périmètre (employés à titre privé, fournisseurs non mandants…).</li><li>Prévoyez la restitution et la destruction des données.</li></ol>',NULL,NULL,40,1,2),
(71,44,'Étude de cas : la dérive d''un outil','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un analyste mandaté pour auditer l''exposition d''une entreprise utilise ensuite les mêmes outils pour réunir des informations sur la vie privée d''un dirigeant concurrent, « par curiosité ». L''affaire est révélée.</p>\n<ol><li>Quelles limites du mandat ont été franchies ?</li><li>Quelles infractions sont potentiellement constituées ?</li><li>Quelles conséquences pour l''analyste, son cabinet et le client ?</li><li>Quels contrôles internes auraient prévenu la dérive ?</li></ol>',NULL,NULL,30,1,3),
(72,45,'Briefing vidéo : l''information comme avantage','video','<p>Les trois piliers de l''intelligence économique.</p>',NULL,19,4,1,1),
(73,45,'Les trois piliers','text','<p>L''intelligence économique (IE) est la maîtrise et la protection de l''information stratégique utile aux acteurs économiques. Elle se pratique <strong>exclusivement par des moyens légaux</strong> : c''est ce qui la distingue de l''espionnage industriel.</p>\n<h3>1. La veille</h3><p>Surveiller l''environnement : concurrents, technologies, réglementations, marchés, signaux faibles.</p>\n<h3>2. La protection</h3><p>Sécuriser le patrimoine informationnel : savoir-faire, données, brevets, réputation.</p>\n<h3>3. L''influence</h3><p>Agir légitimement sur son environnement : participation aux normes, plaidoyer transparent, communication, réseaux professionnels.</p>\n<h3>Enjeux africains</h3>\n<ul><li>La ZLECAf ouvre un marché de plus de 1,3 milliard de personnes : connaître les règles d''origine et les acteurs devient crucial ;</li><li>Les ressources minières et agricoles attirent une compétition internationale intense ;</li><li>Le paiement mobile et la fintech africaine sont devenus des secteurs d''innovation mondiale à protéger.</li></ul>',NULL,NULL,25,1,2),
(74,46,'Monter un dispositif de veille','text','<h3>Les axes de veille</h3>\n<table><thead><tr><th>Type</th><th>Objet</th><th>Sources ouvertes</th></tr></thead><tbody>\n<tr><td>Concurrentielle</td><td>Produits, prix, stratégies</td><td>Rapports annuels, salons, presse économique</td></tr>\n<tr><td>Technologique</td><td>Innovations, brevets</td><td>Bases de brevets, publications scientifiques</td></tr>\n<tr><td>Réglementaire</td><td>Lois, normes, fiscalité</td><td>Journaux officiels, communautés économiques régionales</td></tr>\n<tr><td>Sociétale</td><td>Opinion, attentes</td><td>Réseaux sociaux publics, études</td></tr>\n</tbody></table>\n<h3>Le processus</h3>\n<ol><li>Définir les <strong>facteurs critiques de succès</strong> et les questions clés ;</li><li>Sélectionner et qualifier les sources ;</li><li>Mettre en place des alertes et une revue régulière ;</li><li>Analyser et diffuser un bulletin court ;</li><li>Mesurer l''utilité auprès des destinataires.</li></ol>\n<div class="callout">Les <strong>signaux faibles</strong> — informations fragmentaires annonçant un changement — sont la vraie valeur ajoutée de la veille. Ils ne prennent sens que s''ils sont rapprochés et discutés.</div>',NULL,NULL,25,1,1),
(75,47,'Protéger la valeur','text','<ul><li><strong>Propriété intellectuelle</strong> : brevets, marques, dessins — en Afrique, via l''OAPI (espace francophone) et l''ARIPO (espace anglophone) en complément des offices nationaux ;</li><li><strong>Secret des affaires</strong> : protection des informations confidentielles par des mesures raisonnables (contrats, accès restreints) ;</li><li><strong>Contrats</strong> : clauses de confidentialité et de non-concurrence dans les partenariats ;</li><li><strong>Réputation</strong> : surveillance des atteintes, plan de réponse aux campagnes de dénigrement.</li></ul>\n<h3>Situations à risque</h3>\n<p>Joint-ventures, transferts de technologie, levées de fonds, délégations étrangères, recrutement de profils issus de la concurrence, stagiaires et visites de site.</p>\n<div class="note">Protéger n''est pas se fermer : il s''agit de partager <em>ce qu''il faut, avec qui il faut, au bon moment</em>.</div>',NULL,NULL,25,1,1),
(76,48,'La note stratégique','text','<p>La note stratégique éclaire une décision de long terme. Elle tient en deux à quatre pages.</p>\n<ol><li><strong>Question posée</strong> et contexte en trois lignes ;</li><li><strong>Messages clés</strong> (3 à 5 puces) ;</li><li><strong>Analyse</strong> : facteurs, acteurs, tendances ;</li><li><strong>Scénarios</strong> : tendanciel, favorable, défavorable ;</li><li><strong>Options</strong> avec avantages, risques, coûts ;</li><li><strong>Recommandation</strong> argumentée ;</li><li><strong>Indicateurs de suivi</strong>.</li></ol>\n<p>Outils utiles : analyse PESTEL, SWOT, cartographie des parties prenantes, matrice des scénarios.</p>',NULL,NULL,25,1,1),
(77,49,'Fiche de synthèse (PDF)','document','<p>Modèles de bulletin de veille et de note stratégique.</p>',NULL,20,10,1,1),
(78,49,'Exercice : bulletin de veille','exercise','<p>Pour une PME fictive de transformation de cajou souhaitant exporter dans la ZLECAf :</p>\n<ol><li>Définissez trois questions clés de veille.</li><li>Proposez dix sources ouvertes qualifiées.</li><li>Rédigez un bulletin d''une page avec trois informations commentées et un signal faible.</li></ol>',NULL,NULL,45,1,2),
(79,49,'Étude de cas : la négociation de licence','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une startup de paiement mobile négocie une licence de sa technologie avec un groupe étranger. Lors des réunions, le partenaire demande des détails techniques de plus en plus précis, sans engagement signé.</p>\n<ol><li>Quels risques pour la startup ?</li><li>Quelles protections juridiques mettre en place avant la prochaine réunion ?</li><li>Rédigez les messages clés d''une note stratégique au conseil d''administration.</li></ol>',NULL,NULL,35,1,3),
(80,50,'Briefing vidéo : un continent pluriel','video','<p>Les grandes clés de lecture géopolitique du continent.</p>',NULL,21,4,1,1),
(81,50,'Grilles de lecture du continent','text','<h3>Les acteurs</h3>\n<ul><li><strong>Union africaine</strong> : Conseil de paix et de sécurité, Agenda 2063 ;</li><li><strong>Communautés économiques régionales</strong> : CEDEAO, CEEAC, SADC, EAC, IGAD, UMA, COMESA… ;</li><li><strong>États</strong> et leurs intérêts propres ;</li><li><strong>Acteurs non étatiques</strong> : entreprises, diasporas, organisations religieuses, groupes armés ;</li><li><strong>Puissances extérieures</strong> et nouveaux partenaires.</li></ul>\n<h3>Les espaces stratégiques</h3>\n<table><thead><tr><th>Espace</th><th>Enjeux</th></tr></thead><tbody>\n<tr><td>Sahel</td><td>Sécurité, gouvernance, climat, migrations</td></tr>\n<tr><td>Golfe de Guinée</td><td>Sûreté maritime, hydrocarbures, ports</td></tr>\n<tr><td>Corne de l''Afrique</td><td>Mer Rouge, routes commerciales, eau du Nil</td></tr>\n<tr><td>Grands Lacs</td><td>Ressources minières, frontières, déplacés</td></tr>\n<tr><td>Afrique australe</td><td>Intégration industrielle, énergie, minerais critiques</td></tr>\n</tbody></table>\n<h3>Les dynamiques transversales</h3>\n<p>Démographie (population très jeune), urbanisation rapide, transition énergétique et minerais critiques, numérisation, effets du changement climatique, recompositions des alliances internationales.</p>\n<div class="callout">Méthode : toujours croiser l''échelle locale, nationale, régionale et internationale. Une crise locale a souvent des racines et des effets à d''autres échelles.</div>',NULL,NULL,30,1,2),
(82,51,'Grille d''analyse des conflits','text','<p>Un conflit s''analyse selon trois dimensions complémentaires.</p>\n<h3>1. Profil</h3><p>Contexte historique, géographique, politique, économique et social.</p>\n<h3>2. Causes</h3>\n<ul><li><strong>Structurelles</strong> : inégalités, accès à la terre et à l''eau, gouvernance ;</li><li><strong>Accélératrices</strong> : crise économique, élection contestée, choc climatique ;</li><li><strong>Déclencheurs</strong> : incident, assassinat, décision politique.</li></ul>\n<h3>3. Acteurs</h3>\n<p>Pour chaque acteur : intérêts, positions, capacités, alliances, et ceux qui ont intérêt à la paix (les « connecteurs ») autant que ceux qui ont intérêt au conflit.</p>\n<h3>Dynamiques et scénarios</h3>\n<p>On identifie les tendances, les fenêtres d''opportunité pour la paix et les indicateurs d''alerte précoce. Les mécanismes africains d''alerte précoce (comme le système continental de l''UA ou ECOWARN de la CEDEAO) reposent sur ce type d''indicateurs.</p>\n<div class="warning">L''analyse de conflit exige une grande prudence : éviter les lectures ethnicisantes simplistes, donner la parole aux sources locales et respecter la dignité des victimes.</div>',NULL,NULL,30,1,1),
(83,52,'Évaluer le risque pays','text','<p>Le risque pays mesure la probabilité que des événements liés à un pays affectent négativement un projet ou une organisation.</p>\n<table><thead><tr><th>Dimension</th><th>Exemples d''indicateurs</th></tr></thead><tbody>\n<tr><td>Politique</td><td>Stabilité institutionnelle, calendrier électoral, relations régionales</td></tr>\n<tr><td>Sécuritaire</td><td>Incidents, zones à risque, criminalité</td></tr>\n<tr><td>Économique</td><td>Croissance, inflation, dette, change</td></tr>\n<tr><td>Juridique</td><td>Sécurité des contrats, fiscalité, efficacité judiciaire</td></tr>\n<tr><td>Opérationnel</td><td>Infrastructures, logistique, énergie</td></tr>\n<tr><td>Environnemental et social</td><td>Climat, acceptation locale, droits humains</td></tr>\n</tbody></table>\n<h3>Méthode</h3>\n<ol><li>Définir le projet (le risque dépend toujours de l''exposition) ;</li><li>Noter chaque dimension avec des critères explicites ;</li><li>Pondérer selon le projet ;</li><li>Analyser les tendances, pas seulement l''instantané ;</li><li>Proposer des mesures d''atténuation.</li></ol>\n<div class="note">Un score ne remplace pas l''analyse. Les notations globales doivent être lues avec leurs hypothèses ; un même pays peut présenter des risques très différents selon les régions et les secteurs.</div>',NULL,NULL,30,1,1),
(84,53,'Fiche de synthèse (PDF)','document','<p>Grille d''analyse de conflit et matrice de risque pays.</p>',NULL,22,10,1,1),
(85,53,'Exercice : matrice de risque pays','exercise','<p><strong>Projet fictif :</strong> implantation d''une unité de transformation agricole dans la « République de Kanaga » (pays imaginaire côtier d''Afrique de l''Ouest, 18 millions d''habitants, élections dans 14 mois, inflation à 9 %, port moderne, tensions foncières dans le nord).</p>\n<ol><li>Notez chacune des six dimensions de 1 à 5 avec justification.</li><li>Pondérez selon le projet.</li><li>Rédigez trois scénarios à deux ans.</li><li>Proposez cinq mesures d''atténuation.</li></ol>',NULL,NULL,50,1,2),
(86,53,'Étude de cas : crise dans la région des « Trois Rivières »','case_study','<p><strong>Scénario pédagogique entièrement fictif.</strong> Dans une région frontalière imaginaire, une sécheresse prolongée aggrave les tensions entre agriculteurs et éleveurs. Un incident sur un point d''eau dégénère. Des rumeurs circulent en ligne.</p>\n<ol><li>Réalisez le profil, l''analyse des causes et la cartographie des acteurs.</li><li>Identifiez trois connecteurs pour la paix.</li><li>Proposez cinq indicateurs d''alerte précoce.</li><li>Quelles précautions de vocabulaire et de sources adopter ?</li></ol>',NULL,NULL,40,1,3);
