INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(1,1,1,'Quelle est la caractéristique principale qui distingue le renseignement de la simple information ?','Le renseignement se définit par sa finalité (aider une décision) et par le travail d''évaluation, non par le secret de ses sources.',1),
(2,1,1,'Dans le cycle du renseignement, quelle phase consiste à traduire le besoin du décideur en questions précises ?','L''orientation transforme une préoccupation générale en besoins en renseignement exploitables.',1),
(3,1,1,'Un renseignement exact livré après la décision qu''il devait éclairer :','Le délai fait partie de la qualité : un produit tardif ne remplit plus sa fonction.',1),
(4,1,2,'Que désignait l''expression « cabinet noir » dans les monarchies européennes ?','Les cabinets noirs interceptaient et déchiffraient la correspondance diplomatique.',1),
(5,1,2,'Quel rôle jouaient les caravanes transsahariennes dans les empires sahéliens ?','Commerce et information circulaient ensemble sur les routes caravanières.',1),
(6,1,2,'Quelle tendance caractérise l''évolution des services depuis les années 1990 ?','Lois, organes de contrôle et coopérations régionales se sont développés.',1),
(7,1,3,'Que signifie l''acronyme OSINT ?','OSINT : renseignement d''origine sources ouvertes.',1),
(8,1,3,'Deux articles de presse reprenant la même dépêche d''agence constituent :','Il faut remonter à l''origine : une même dépêche reprise reste une seule source.',1),
(9,1,3,'Quelle limite principale présente le GEOINT ?','L''imagerie montre des faits physiques, pas des intentions.',1),
(10,1,4,'Dans la méthode ACH, sur quels indices l''analyste concentre-t-il son attention ?','L''ACH privilégie la réfutation : l''hypothèse retenue est la moins contredite.',1),
(11,1,4,'Supposer qu''un acteur étranger raisonne exactement comme nous relève :','L''effet miroir projette notre propre logique sur autrui.',1),
(12,1,4,'Pourquoi utiliser une échelle de probabilité définie à l''avance ?','Un vocabulaire stable garantit que « probable » signifie la même chose pour tous.',1),
(13,2,6,'Pour une entreprise privée, quelle pratique HUMINT est légitime ?','Seuls les échanges transparents et consentis sont acceptables pour un acteur privé.',1),
(14,2,6,'Quel apport spécifique le HUMINT offre-t-il par rapport aux capteurs techniques ?','Les intentions humaines échappent largement aux capteurs techniques.',1),
(15,2,6,'Le recrutement de sources clandestines relève :','Cette activité est réservée aux autorités habilitées par la loi.',1),
(16,2,7,'Pourquoi archiver URL, date et capture lors d''une collecte OSINT ?','La traçabilité permet la vérification par un tiers et protège contre la disparition des contenus.',1),
(17,2,7,'Une information publiquement accessible sur une personne :','L''accessibilité ne lève pas les obligations légales de protection des données.',1),
(18,2,7,'Créer un faux profil pour entrer dans un groupe privé est :','L''OSINT éthique se limite aux contenus réellement publics, sans tromperie.',1),
(19,2,8,'Que désigne le COMINT ?','COMINT = Communications Intelligence, sous-ensemble du SIGINT.',1),
(20,2,8,'Dans un État de droit, une mesure d''interception doit notamment être :','Légalité, proportionnalité, autorisation et contrôle sont les piliers du cadre.',1),
(21,2,8,'L''interception de communications par une entreprise privée :','Elle est réservée aux autorités publiques habilitées par la loi.',1),
(22,2,9,'Que mesure la résolution spatiale d''une image ?','La résolution spatiale correspond à la taille au sol d''un pixel.',1),
(23,2,9,'Quel critère de photo-interprétation renseigne sur la hauteur d''un objet ?','La longueur de l''ombre permet d''estimer la hauteur, connaissant l''heure et la position du soleil.',1),
(24,2,9,'Pourquoi comparer deux images d''une même zone à des dates différentes ?','L''analyse diachronique révèle les évolutions du terrain.',1),
(25,3,11,'Que signifie le principe du « besoin d''en connaître » ?','La collecte doit être ciblée sur un besoin défini.',1),
(26,3,11,'Dans un cadre privé, le consentement éclairé implique que l''interlocuteur :','Transparence sur l''identité et la finalité : c''est la base de l''éthique.',1),
(27,3,11,'Quelle vigilance s''impose face à un acteur économique local ?','Chaque profil a ses biais : ici, les intérêts commerciaux.',1),
(28,3,12,'Laquelle de ces pratiques constitue une ligne rouge absolue ?','L''usurpation d''identité ou de qualité est illégale et contraire à l''éthique.',1),
(29,3,12,'Quel texte africain encadre la protection des données personnelles à l''échelle continentale ?','La Convention de l''UA de 2014, dite de Malabo.',1),
(30,3,12,'Selon le test des quatre questions, que faire si une seule réponse est négative ?','Une seule réponse négative suffit à renoncer.',1),
(31,3,13,'Dans la méthode de l''entonnoir, quand pose-t-on les questions fermées ?','On part du général (ouvert) pour aller vers la vérification (fermé).',1),
(32,3,13,'Laquelle de ces questions est suggestive ?','Elle oriente la réponse et contamine l''information.',1),
(33,3,13,'L''observation non intrusive d''un espace public porte sur :','On observe des flux et des usages, jamais des individus.',1),
(34,3,14,'Que signifie la cotation « B2 » ?','La lettre cote la source, le chiffre cote l''information.',1),
(35,3,14,'Pourquoi coter séparément la source et l''information ?','Les deux dimensions sont indépendantes.',1),
(36,3,14,'Qu''est-ce qu''un « rapport circulaire » ?','Il donne une fausse impression de confirmation.',1),
(37,4,16,'À quoi sert la pseudonymisation d''une source ?','Le code remplace l''identité ; la correspondance est stockée à part.',1),
(38,4,16,'Pourquoi un rapport sans nom peut-il malgré tout exposer une source ?','Le risque de recoupement impose une relecture attentive.',1),
(39,4,16,'Quelle mesure relève de l''hygiène numérique ?','Le chiffrement protège en cas de perte ou de vol.',1),
(40,4,17,'Que montrent les méta-analyses sur la détection du mensonge à partir du comportement ?','Autour de 54 % : guère mieux que le hasard.',1),
(41,4,17,'Existe-t-il un signe non verbal universel du mensonge ?','La recherche n''a identifié aucun indice universel.',1),
(42,4,17,'Quelle approche est jugée plus fiable ?','Le contenu vérifiable et les entretiens non accusatoires donnent de meilleurs résultats.',1),
(43,4,18,'Que signifie BLUF ?','La conclusion est placée en tête du document.',1),
(44,4,18,'Quelle formulation est la plus professionnelle ?','Faits chiffrés + jugement probabiliste + niveau de confiance.',1),
(45,4,18,'Que doit contenir la section « lacunes et indicateurs » ?','Elle prépare le suivi et l''actualisation de l''analyse.',1),
(46,5,20,'Pour une organisation privée, le contre-espionnage consiste principalement à :','L''approche est défensive ; les enquêtes relèvent des autorités.',1),
(47,5,20,'Quelle est la cause la plus fréquente des fuites d''informations ?','Conversations, réseaux sociaux, négligences : le facteur humain domine.',1),
(48,5,20,'Un consultant posant des questions insistantes hors de sa mission relève de :','C''est un vecteur humain classique.',1),
(49,5,21,'Quel est le profil de menace interne le plus fréquent ?','L''erreur et la méconnaissance des règles dominent.',1),
(50,5,21,'Le principe du moindre privilège consiste à :','Chacun n''accède qu''à ce dont il a besoin.',1);
INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(51,5,21,'Quelle mesure réduit durablement le risque interne ?','Le climat organisationnel est un facteur clé.',1),
(52,5,22,'Par quoi commence une démarche de protection de l''information ?','On identifie d''abord ce qui doit être protégé.',1),
(53,5,22,'Pourquoi limiter le nombre de niveaux de classification ?','La simplicité favorise l''adoption.',1),
(54,5,22,'Laquelle est une mesure de protection physique ?','Broyage et politique du bureau propre relèvent de la sécurité physique.',1),
(55,5,23,'« Votre compte sera bloqué dans une heure » exploite principalement le levier :','L''urgence empêche la réflexion.',1),
(56,5,23,'Quelle est la meilleure parade face à une demande inhabituelle de virement ?','Le contre-appel par un canal indépendant déjoue la fraude au président.',1),
(57,5,23,'Un salarié qui signale une tentative d''hameçonnage après avoir cliqué doit être :','Blâmer décourage les signalements, pourtant essentiels.',1),
(58,6,25,'Quelle vérification est appropriée lors d''un recrutement ?','Les vérifications doivent rester légales et proportionnées.',1),
(59,6,25,'Que doit inclure la procédure de départ d''un salarié ?','Des comptes actifs après départ sont un risque majeur.',1),
(60,6,25,'Le « duty of care » désigne :','Il impose d''évaluer et de couvrir les risques des missions.',1),
(61,6,26,'Le risque résulte de la combinaison de :','Les trois composantes doivent être évaluées.',1),
(62,6,26,'Les trois critères d''évaluation d''une menace sont :','Intention + capacité + opportunité.',1),
(63,6,26,'Pourquoi actualiser régulièrement une matrice de risques ?','Une analyse figée devient trompeuse.',1),
(64,6,27,'Que signifie la « défense en profondeur » ?','Plusieurs couches évitent qu''une seule défaillance soit fatale.',1),
(65,6,27,'Les sauvegardes testées relèvent de quelle fonction ?','Elles permettent le rétablissement après incident.',1),
(66,6,27,'Face à une attaque, une organisation privée doit :','La riposte offensive est illégale ; on signale.',1),
(67,6,28,'Qu''est-ce qu''un « inject » dans un exercice sur table ?','Les injects font évoluer le scénario.',1),
(68,6,28,'Le scénario d''un exercice doit être :','Le fictif évite toute mise en cause réelle.',1),
(69,6,28,'Qu''est-ce qu''un exercice réussi ?','L''objectif est d''apprendre.',1),
(70,7,30,'Que signifie l''acronyme APT ?','Désigne des groupes sophistiqués et persistants.',1),
(71,7,30,'Pourquoi étudier la chaîne d''attaque ?','C''est un outil de conception défensive.',1),
(72,7,30,'Quelle étape repose souvent sur les sources ouvertes ?','D''où l''intérêt de réduire son exposition publique.',1),
(73,7,31,'Que permet l''opérateur filetype: ?','Ex. filetype:pdf.',1),
(74,7,31,'Qu''appelle-t-on « pivoter » en OSINT ?','Domaine → certificat → infrastructure, etc.',1),
(75,7,31,'Quelle règle d''hygiène est essentielle ?','L''enquêteur observe sans interagir.',1),
(76,7,32,'Qu''est-ce que l''empreinte numérique d''une organisation ?','Sites, documents, profils, sous-domaines…',1),
(77,7,32,'Un audit d''exposition sur une organisation tierce nécessite :','Sans autorisation, la démarche est contestable.',1),
(78,7,32,'Pourquoi les offres d''emploi peuvent-elles être sensibles ?','Elles informent un attaquant sur l''environnement technique.',1),
(79,7,33,'Que désigne EXIF ?','EXIF stocke les informations de prise de vue.',1),
(80,7,33,'Pourquoi calculer l''empreinte SHA-256 d''un fichier original ?','L''empreinte garantit l''intégrité.',1),
(81,7,33,'Une métadonnée de date isolée constitue :','Elle peut être erronée ou falsifiée.',1),
(82,8,35,'Les indicateurs de compromission (IoC) relèvent principalement du niveau :','Ils servent directement aux équipes techniques.',1),
(83,8,35,'Quels sont les quatre sommets du modèle en diamant ?','Ils structurent l''analyse d''un événement.',1),
(84,8,35,'Selon la pyramide de la douleur, qu''est-ce qui gêne le plus un attaquant ?','Changer de comportement est coûteux pour l''adversaire.',1),
(85,8,36,'Quel registre attribue les adresses IP en Afrique ?','AFRINIC est le registre Internet régional africain.',1),
(86,8,36,'Les journaux de transparence des certificats permettent :','Ils sont publics et utiles pour découvrir des domaines.',1),
(87,8,36,'Plusieurs domaines frauduleux sur une même IP suggèrent :','C''est une hypothèse à confirmer.',1),
(88,8,37,'Le chiffrement de bout en bout garantit que :','Le fournisseur n''a pas accès au contenu.',1),
(89,8,37,'Même chiffrées, les communications peuvent révéler :','Les métadonnées restent souvent visibles.',1),
(90,8,37,'Pourquoi vérifier les codes de sécurité d''un contact ?','Cela protège contre l''attaque de l''intercepteur.',1),
(91,8,38,'Qu''est-ce qu''un « voyage impossible » ?','Indice fort d''utilisation d''identifiants par un tiers.',1),
(92,8,38,'Une règle de transfert automatique vers l''extérieur créée la nuit est :','C''est un mode opératoire courant d''exfiltration.',1),
(93,8,38,'Avant d''agir sur une alerte, il faut :','Distinguer vrai et faux positif.',1),
(94,9,40,'Quelle est la fonction principale de Maltego ?','Maltego représente des liens entre entités.',1),
(95,9,40,'Un usage légitime de Shodan est :','Il sert notamment à mesurer sa propre exposition.',1),
(96,9,40,'Profiler une personne privée avec ces outils :','C''est une ligne rouge.',1),
(97,9,41,'Capturer le trafic d''un réseau dont on n''est pas responsable :','Sans autorisation, c''est une interception illicite.',1),
(98,9,41,'Volatility sert à analyser :','C''est un outil d''analyse mémoire.',1),
(99,9,41,'Sur quoi travaille-t-on lors d''une investigation de support ?','L''original est préservé.',1),
(100,9,42,'Un usage légitime des jumelles d''observation est :','Observation de lieux publics uniquement.',1);
INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(101,9,42,'Poser un traceur GPS sur le véhicule d''autrui est :','C''est une atteinte à la vie privée.',1),
(102,9,42,'Un broyeur de documents relève de :','Il protège contre la récupération de documents jetés.',1),
(103,9,43,'Quel document rédiger avant une investigation outillée ?','Elle formalise finalité, mandat, périmètre et légalité.',1),
(104,9,43,'Le principe de proportionnalité impose de choisir :','L''intrusion doit être minimale.',1),
(105,9,43,'Pourquoi définir une durée de conservation des données ?','Conserver indéfiniment est contraire au droit des données.',1),
(106,10,45,'Qu''est-ce qui distingue l''intelligence économique de l''espionnage industriel ?','L''IE est légale par définition.',1),
(107,10,45,'Quels sont les trois piliers de l''IE ?','Ce triptyque structure toute démarche.',1),
(108,10,45,'La ZLECAf est :','Elle redéfinit le paysage économique africain.',1),
(109,10,46,'La surveillance des journaux officiels relève de la veille :','Lois, décrets et normes.',1),
(110,10,46,'Qu''est-ce qu''un signal faible ?','Il annonce une évolution potentielle.',1),
(111,10,46,'Par quoi commence un dispositif de veille ?','On sait d''abord ce que l''on cherche.',1),
(112,10,47,'Quel office régional gère la propriété intellectuelle dans l''espace francophone africain ?','L''Organisation africaine de la propriété intellectuelle.',1),
(113,10,47,'Le secret des affaires protège une information si :','La protection doit être organisée.',1),
(114,10,47,'Laquelle est une situation à risque ?','Elle implique un partage important d''informations.',1),
(115,10,48,'Combien de scénarios une note stratégique présente-t-elle classiquement ?','Trois scénarios contrastés.',1),
(116,10,48,'PESTEL analyse les facteurs :','Un outil d''analyse de l''environnement.',1),
(117,10,48,'Où place-t-on les messages clés ?','Le décideur doit les lire en premier.',1),
(118,11,50,'Quel organe de l''UA traite des questions de sécurité ?','Le CPS est l''organe décisionnel en la matière.',1),
(119,11,50,'Quel enjeu caractérise le Golfe de Guinée ?','Piraterie et sécurité portuaire.',1),
(120,11,50,'Pourquoi croiser plusieurs échelles d''analyse ?','Local, national, régional et international interagissent.',1),
(121,11,51,'Une élection contestée est généralement une cause :','Elle accentue des tensions existantes.',1),
(122,11,51,'Que sont les « connecteurs » dans l''analyse de conflit ?','Ils sont des leviers de résolution.',1),
(123,11,51,'ECOWARN est le système d''alerte précoce de :','Mécanisme de la CEDEAO.',1),
(124,11,52,'Le risque pays dépend :','Un même pays présente des risques différents selon les projets.',1),
(125,11,52,'La sécurité des contrats relève de la dimension :','Elle concerne le cadre légal et judiciaire.',1),
(126,11,52,'Pourquoi analyser les tendances ?','La trajectoire compte autant que la situation présente.',1);
