(10,3,'N''a quasiment plus de valeur opérationnelle',1,2),
(11,3,'Devient automatiquement stratégique',0,3),
(12,3,'Doit être reclassifié',0,4),
(13,4,'Une prison secrète',0,1),
(14,4,'Un service chargé d''ouvrir et de déchiffrer le courrier',1,2),
